window.REVISION_SUBJECTS.push({"config":{"brandIcon":"☪️","brandSubtitle":"AQA GCSE Religious Studies A (8062)","brandTitle":"Islam (AQA RS A)","breadcrumb":"Religious Studies / AQA A / Islam","examBoard":"AQA GCSE","footerNote":"Original practice questions written to the AQA GCSE Religious Studies A (8062) specification. Not past-paper material. Model answers are indicative exemplars, not official AQA mark schemes; other well-argued answers can gain full credit.","heroEyebrow":"Component 1 · Islam · Beliefs \u0026 teachings · Practices","markingSchemaId":"aqa-rs-generic","pageTitle":"AQA GCSE Religious Studies A: Islam Revision","papers":[{"id":"Beliefs","label":"Beliefs \u0026 teachings","subtitle":"Key beliefs and authority (1.1-1.9)","title":"Islam: Beliefs and teachings"},{"id":"Practices","label":"Practices","subtitle":"Worship, duties and festivals (2.1-2.8)","title":"Islam: Practices"}],"storageId":"aqa_rs_a_islam","subjectArea":"Religious Studies","subjectName":"Islam"},"questions":{"paper1":[{"id":"aqa-rs-a-islam-paper1-1-1-0","paper":"Beliefs","module":"1.1","moduleTitle":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","question":"Which of the following is one of the five roots of Usul ad-Din in Shi'a Islam but is NOT listed separately among the six articles of faith in Sunni Islam?\nA Tawhid (oneness of God)\nB Imamah (leadership by the Imams)\nC Malaikah (angels)\nD Akhirah (life after death)","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Imamah, belief in the divinely appointed Imams beginning with Ali, is a distinct Shi'a root of faith. Tawhid and the afterlife appear in both lists, and angels are a Sunni article.","evidence":["Five roots: Tawhid, Adalat, Nubuwwah, Imamah, Mi'ad"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Usul ad-Din"},{"id":"aqa-rs-a-islam-paper1-1-1-1","paper":"Beliefs","module":"1.1","moduleTitle":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","question":"Which of these is one of the six articles of faith in Sunni Islam?\nA Khums\nB Al-Qadr (predestination)\nC Hajj\nD Adalat","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Belief in al-Qadr, Allah's decree, is the sixth article named in the Hadith of Jibril. Khums and Hajj are practices; Adalat is a Shi'a root.","evidence":["Hadith of Jibril (Sahih Muslim)"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"six articles"},{"id":"aqa-rs-a-islam-paper1-1-1-2","paper":"Beliefs","module":"1.1","moduleTitle":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","question":"Give two of the six articles of faith in Sunni Islam.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: belief in Allah's oneness (Tawhid); belief in angels (malaikah); belief in the holy books (kutub); belief in the prophets (risalah/rusul); belief in the Day of Judgement and life after death (Akhirah); belief in predestination (al-Qadr).","evidence":["Qur'an 4:136","Hadith of Jibril"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"six articles"},{"id":"aqa-rs-a-islam-paper1-1-1-3","paper":"Beliefs","module":"1.1","moduleTitle":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","question":"Give two of the five roots of Usul ad-Din in Shi'a Islam.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: Tawhid (oneness of God); Adalat (God's justice); Nubuwwah (prophethood); Imamah (the leadership of the twelve Imams); Mi'ad (the Day of Judgement and resurrection).","evidence":["Usul ad-Din = 'roots of religion'"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"Usul ad-Din"},{"id":"aqa-rs-a-islam-paper1-1-1-4","paper":"Beliefs","module":"1.1","moduleTitle":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","question":"Explain two similarities between the six articles of faith in Sunni Islam and the five roots of Usul ad-Din in Shi'a Islam.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Both begin with Tawhid, the oneness of Allah. Sunni and Shi'a Muslims alike believe God is one and without partners, so committing shirk is the gravest sin in both traditions and every other belief depends on this one.\n\n2. Both include belief in prophethood and in the Day of Judgement. Sunnis call these risalah and Akhirah and Shi'as call them Nubuwwah and Mi'ad, but both accept that Allah sent prophets ending with Muhammad and that all people will be resurrected and judged, which gives life a moral purpose.","evidence":["Tawhid","Risalah / Nubuwwah","Akhirah / Mi'ad"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"similarities"},{"id":"aqa-rs-a-islam-paper1-1-1-5","paper":"Beliefs","module":"1.1","moduleTitle":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","question":"Explain two differences between the six articles of faith in Sunni Islam and the five roots of Usul ad-Din in Shi'a Islam.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Shi'a Islam includes Imamah as a root of faith. Shi'as believe Allah appointed Ali and eleven of his descendants as infallible leaders after Muhammad, whereas Sunnis do not hold this as an article of faith and accept leaders (caliphs) chosen by the community.\n\n2. Shi'a Islam names Adalat (God's justice) as a separate root. Shi'as emphasise that God is perfectly just and would never punish people for what they could not choose, so human free will matters; Sunnis believe God is just too but list al-Qadr (predestination) as a separate article instead, stressing God's control over all events.","evidence":["Imamah","Adalat","Al-Qadr"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"differences"},{"id":"aqa-rs-a-islam-paper1-1-1-6","paper":"Beliefs","module":"1.1","moduleTitle":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","question":"Explain two reasons why the six articles of faith are important to Sunni Muslims.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. They define what it means to be a believer (mu'min). The Qur'an warns that whoever disbelieves in Allah, His angels, His books, His messengers and the Last Day 'has certainly gone far astray' (Qur'an 4:136), so accepting these beliefs is necessary for true faith rather than an optional extra.\n\n2. They come from the Prophet's own teaching. In the Hadith of Jibril, the angel Jibril, appearing as a man, asked Muhammad what iman (faith) is, and the Prophet listed belief in Allah, angels, books, messengers, the Last Day and divine decree. Because this comes from the Prophet, Sunnis treat the six articles as a summary of authentic belief that shapes worship and daily life, e.g. knowing they will be judged encourages honesty.","evidence":["Qur'an 4:136","Hadith of Jibril (Sahih Muslim, Book of Faith)"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"importance"},{"id":"aqa-rs-a-islam-paper1-1-1-7","paper":"Beliefs","module":"1.1","moduleTitle":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","question":"Explain two of the roots of Usul ad-Din and why they are important for Shi'a Muslims.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Adalat (divine justice): Shi'as believe Allah always acts justly and never wrongs anyone. The Qur'an says 'Indeed, Allah does not do injustice, even as much as an atom's weight' (Qur'an 4:40). This gives believers confidence that judgement will be fair and that humans have genuine free will, so they are responsible for their actions.\n\n2. Imamah (leadership): Shi'as believe Allah appointed the Imams to guide the community after the Prophet. They point to the event at Ghadir Khumm, where the Prophet said 'Whoever I am his master (mawla), Ali is his master'. This root is important because it explains why Shi'as follow the teachings of the Imams and, today, senior scholars (marja') who represent the hidden twelfth Imam.","evidence":["Qur'an 4:40","Hadith of Ghadir Khumm"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"Usul ad-Din"},{"id":"aqa-rs-a-islam-paper1-1-1-8","paper":"Beliefs","module":"1.1","moduleTitle":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","question":"‘The differences between Sunni and Shi'a beliefs are more important than the similarities.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nImamah is a real and lasting difference. For Shi'a Muslims, belief that Ali and the eleven Imams after him were divinely chosen and infallible is a root of faith (Usul ad-Din). Sunnis reject this, accepting Abu Bakr, Umar, Uthman and Ali as rightly guided caliphs chosen by the community. This disagreement about who had authority after the Prophet's death in 632 CE has shaped separate schools of law, different hadith collections and different leaders of religious authority, such as Shi'a marja' (e.g. Ayatollah Sistani) compared with Sunni scholars and muftis.\n\nSome argue these differences have had serious consequences. Sectarian violence in countries such as Iraq, Pakistan and Syria shows how deeply people can feel about them. Also, the emphasis on Adalat in Shi'a thought and on al-Qadr in Sunni thought leads to differences in how believers think about free will and God's control.\n\nARGUMENTS AGAINST THE STATEMENT\nHowever, the core of the two lists is the same. Both start with Tawhid, the belief that 'He is Allah, the One' (Qur'an 112:1); both include prophethood, ending with Muhammad as the 'Seal of the Prophets' (Qur'an 33:40); and both include the resurrection and Day of Judgement. Sunnis also believe God is just, and Shi'as also believe in angels, holy books and God's decree; they simply organise the beliefs differently. Both read the same Qur'an, face the same qiblah and perform the same Hajj.\n\nMany Muslims stress the ummah (worldwide community). The Qur'an says 'hold firmly to the rope of Allah all together and do not become divided' (Qur'an 3:103). The Amman Message (2004), endorsed by hundreds of Sunni and Shi'a scholars, recognised both as valid Muslims. In Britain, Sunni and Shi'a Muslims often attend each other's mosques and work together in organisations such as the Muslim Council of Britain.\n\nCONCLUSION\nThe difference over Imamah is genuine and historically important, so it cannot be dismissed. But it concerns how guidance continues after the Prophet, not who God is or what salvation depends on. Since the beliefs about Allah, the Prophet, the Qur'an and the afterlife are shared, and these are the foundation of everything else, I conclude that the similarities are more important than the differences, even though the differences explain real variety within Islam.","evidence":["Qur'an 112:1","Qur'an 33:40","Qur'an 3:103","Amman Message (2004)","Imamah"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Sunni and Shi'a"},{"id":"aqa-rs-a-islam-paper1-1-1-9","paper":"Beliefs","module":"1.1","moduleTitle":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","question":"‘Belief in al-Qadr (predestination) is the most important of the six articles of faith.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nSome Sunni Muslims argue that al-Qadr is vital because it shapes how a believer lives every day. Believing that 'all things We created with predestination' (Qur'an 54:49) helps Muslims accept suffering with patience (sabr), trust in Allah (tawakkul) and say 'Insha'Allah' (if God wills) about the future. The Prophet listed it as part of faith in the Hadith of Jibril, and without it a believer might think events are random or that humans are in total control, which would undermine belief in God's power.\n\nIt also links the other articles: the books, angels and Day of Judgement are all part of God's plan, so al-Qadr shows that Allah is in control of history from creation to the end.\n\nARGUMENTS AGAINST THE STATEMENT\nMost Muslims would say Tawhid is the most important article, because every other belief depends on there being one God. Surah 112 is said to be worth a third of the Qur'an, and shirk (associating partners with God) is the one sin Allah will not forgive if a person dies without repenting (Qur'an 4:48). Al-Qadr only makes sense if there is first one all-powerful God whose decree it is.\n\nOthers may argue belief in Akhirah matters more for behaviour, because knowing 'whoever does an atom's weight of good will see it' (Qur'an 99:7) motivates moral action more directly. Shi'a Muslims do not list al-Qadr as one of the five roots; they emphasise Adalat (justice) and human free will, so for them it cannot be the most important.\n\nCONCLUSION\nAl-Qadr is important because it gives Muslims trust and patience, but it depends on Tawhid and is understood differently by Sunni and Shi'a Muslims. Since Tawhid is the foundation of all the other beliefs and is shared by every Muslim, the statement is unconvincing: al-Qadr is important but not the most important article.","evidence":["Qur'an 54:49","Qur'an 4:48","Qur'an 99:7","Surah 112","Hadith of Jibril"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"al-Qadr"},{"id":"aqa-rs-a-islam-paper1-1-2-0","paper":"Beliefs","module":"1.2","moduleTitle":"Tawhid (the Oneness of God), Qur'an Surah 112","question":"Which surah of the Qur'an is most closely associated with Tawhid?\nA Surah 1 (al-Fatihah)\nB Surah 96 (al-Alaq)\nC Surah 112 (al-Ikhlas)\nD Surah 97 (al-Qadr)","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C - Surah 112 declares 'He is Allah, the One... He neither begets nor is born, nor is there to Him any equivalent', the classic summary of Tawhid.","evidence":["Qur'an 112:1-4"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Surah 112"},{"id":"aqa-rs-a-islam-paper1-1-2-1","paper":"Beliefs","module":"1.2","moduleTitle":"Tawhid (the Oneness of God), Qur'an Surah 112","question":"What is the name for the sin of associating partners with Allah?\nA Shirk\nB Sawm\nC Shari'ah\nD Sunnah","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"A - Shirk is treating anything as equal to God or sharing in His divinity; it is the opposite of Tawhid.","evidence":["Qur'an 4:48"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"shirk"},{"id":"aqa-rs-a-islam-paper1-1-2-2","paper":"Beliefs","module":"1.2","moduleTitle":"Tawhid (the Oneness of God), Qur'an Surah 112","question":"Give two things Surah 112 teaches about Allah.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: Allah is One (Ahad); Allah is the Eternal Refuge / self-sufficient, on whom all depend (as-Samad); Allah does not have children (He 'neither begets'); Allah was not born / has no parents; nothing is equal or comparable to Allah.","evidence":["Qur'an 112:1-4"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"Surah 112"},{"id":"aqa-rs-a-islam-paper1-1-2-3","paper":"Beliefs","module":"1.2","moduleTitle":"Tawhid (the Oneness of God), Qur'an Surah 112","question":"Give two ways Muslims show belief in Tawhid in their lives.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: reciting the Shahadah ('There is no god but Allah…'); worshipping only Allah in salah; not having pictures or statues of God or the Prophet in mosques; avoiding shirk such as trusting in charms or idols; beginning actions with 'Bismillah'; decorating mosques with calligraphy and geometric patterns rather than images.","evidence":["Shahadah","Bismillah"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"living Tawhid"},{"id":"aqa-rs-a-islam-paper1-1-2-4","paper":"Beliefs","module":"1.2","moduleTitle":"Tawhid (the Oneness of God), Qur'an Surah 112","question":"Explain two ways belief in Tawhid influences Muslims today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It shapes worship. Because only Allah is worthy of worship, Muslims pray to God alone without intermediaries, and mosques contain no images of God or people; instead they use Arabic calligraphy of Qur'anic verses and geometric patterns that point to God's infinite nature without depicting Him.\n\n2. It shapes priorities in life. If Allah alone is God, nothing else - money, fame, celebrities or possessions - should be treated as if it were ultimate. Many Muslims see putting wealth or status above God as a form of 'hidden shirk', so Tawhid encourages humility, generosity (e.g. paying zakah) and trusting God rather than material things.","evidence":["Shirk","Calligraphy and aniconism in mosques"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"influence"},{"id":"aqa-rs-a-islam-paper1-1-2-5","paper":"Beliefs","module":"1.2","moduleTitle":"Tawhid (the Oneness of God), Qur'an Surah 112","question":"Explain two reasons why shirk is considered the greatest sin in Islam.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It directly contradicts Tawhid, the most basic belief in Islam. To treat anything as equal to Allah denies that He is the One, unique and without partner, so it attacks the foundation on which all other beliefs and practices depend.\n\n2. The Qur'an teaches that it is the one sin Allah will not forgive if a person dies without repenting of it: 'Indeed, Allah does not forgive association with Him, but He forgives what is less than that for whom He wills' (Qur'an 4:48). This shows how seriously it is taken, so Muslims are taught to guard carefully against it.","evidence":["Qur'an 4:48"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"shirk"},{"id":"aqa-rs-a-islam-paper1-1-2-6","paper":"Beliefs","module":"1.2","moduleTitle":"Tawhid (the Oneness of God), Qur'an Surah 112","question":"Explain two Muslim teachings about Tawhid (the Oneness of God).\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Allah is completely one and unique. Surah 112 teaches 'Say: He is Allah, the One. Allah, the Eternal Refuge. He neither begets nor is born, nor is there to Him any equivalent' (Qur'an 112:1-4). This means God cannot be divided, has no family and cannot be compared to anything created, which is why Muslims reject the Christian idea of the Trinity.\n\n2. Allah alone should be worshipped. The first part of the Shahadah, 'There is no god but Allah', expresses this, and the Prophet removed the idols from the Ka'bah when he returned to Makkah in 630 CE. Muslims therefore pray directly to God, and the five daily prayers are a constant reminder that He alone deserves worship.","evidence":["Qur'an 112:1-4","Shahadah","Removal of idols from the Ka'bah (630 CE)"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"Tawhid"},{"id":"aqa-rs-a-islam-paper1-1-2-7","paper":"Beliefs","module":"1.2","moduleTitle":"Tawhid (the Oneness of God), Qur'an Surah 112","question":"Explain two reasons why Tawhid is important to Muslims.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It is the first and most important belief, the foundation of both the six articles and the five roots of Usul ad-Din. Every prophet taught it: 'We sent no messenger before you except that We revealed to him that there is no deity except Me, so worship Me' (Qur'an 21:25). Without belief in one God the other beliefs - angels, books, prophets, judgement - have no basis.\n\n2. It gives a unified view of life. Because one God created everything, all of life - work, family, environment - belongs to Him and should be lived according to His will. This means there is no division between 'religious' and 'everyday' life; even eating or helping a neighbour can be an act of worship ('ibadah) if done for God.","evidence":["Qur'an 21:25","'Ibadah (worship in all of life)"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"Tawhid"},{"id":"aqa-rs-a-islam-paper1-1-2-8","paper":"Beliefs","module":"1.2","moduleTitle":"Tawhid (the Oneness of God), Qur'an Surah 112","question":"‘Tawhid is the most important belief in Islam.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nTawhid is the first of the six articles of faith for Sunni Muslims and the first of the five roots of Usul ad-Din for Shi'a Muslims, so both traditions place it at the very start. The first words of the Shahadah, 'There is no god but Allah', state it, and a person becomes a Muslim by declaring it. The Prophet is reported to have said that Surah 112, which teaches 'He is Allah, the One', is equal to a third of the Qur'an, showing how central it is.\n\nEvery other belief depends on Tawhid. Angels are God's servants, prophets are God's messengers, holy books are God's words and the Day of Judgement is God's judgement. If there were not one God, none of these would make sense. The seriousness of shirk, which Allah will not forgive if unrepented (Qur'an 4:48), also shows that denying Tawhid is the worst possible mistake. The Qur'an says every messenger taught it (Qur'an 21:25).\n\nARGUMENTS AGAINST THE STATEMENT\nSome Muslims might argue that Risalah (prophethood) is equally important, because without the prophets and especially Muhammad people would not know who God is or how to worship Him; the Shahadah has two parts, and the second, 'Muhammad is the messenger of Allah', is also required. Others argue Akhirah matters most in practice, because the knowledge that every action will be judged ('whoever does an atom's weight of evil will see it', Qur'an 99:8) motivates moral behaviour.\n\nShi'a Muslims may argue that Adalat (justice) or Imamah are just as essential, since without trusting that God is just, and without guidance from the Imams, believers could misunderstand God's will. A non-religious person might argue that what matters most in any religion is how people treat others, not abstract beliefs about God's nature.\n\nCONCLUSION\nOther beliefs are vital, and in daily life Muslims may feel the influence of prophethood and judgement very strongly. However, prophethood and judgement themselves only exist because there is one God who sends messengers and judges. As Tawhid is shared by all Muslims, is stated first in the Shahadah and underpins all other beliefs, I agree with the statement that it is the most important belief in Islam.","evidence":["Qur'an 112","Qur'an 4:48","Qur'an 21:25","Qur'an 99:8","Shahadah"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Tawhid"},{"id":"aqa-rs-a-islam-paper1-1-2-9","paper":"Beliefs","module":"1.2","moduleTitle":"Tawhid (the Oneness of God), Qur'an Surah 112","question":"‘Muslims today find it difficult to avoid shirk.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nMany Muslim scholars teach that shirk is not only bowing to idols but also giving anything the devotion that belongs to God. Modern society constantly encourages people to treat money, success, appearance or celebrities as the most important things in life. Social media and consumer culture can make people seek the praise of others, which the Prophet warned about as 'minor shirk' (riya', showing off in worship) in a hadith recorded by Ahmad. In a busy, secular society such as Britain, it can be hard to keep God at the centre when work, school and entertainment take up most of the day.\n\nSome Muslims also worry about superstitious practices, such as relying on amulets or fortune-telling, which some cultures have mixed with Islam. Disagreement among Muslims about practices such as visiting shrines of saints shows that the line between respect and shirk is not always clear to everyone.\n\nARGUMENTS AGAINST THE STATEMENT\nOthers argue that Islam gives Muslims many built-in reminders that make avoiding shirk achievable. The five daily prayers, beginning each with 'Allahu Akbar' (God is greatest), refocus a Muslim on God throughout the day. Reciting Surah 112 and the Shahadah regularly reminds believers that nothing is equal to God. Mosques avoid images of God to prevent idolatry.\n\nIslam also teaches that God is merciful and forgiving. Qur'an 4:48 says God forgives sins other than shirk, and a person who repents sincerely of shirk during their lifetime can be forgiven; the Qur'an also says 'do not despair of the mercy of Allah' (Qur'an 39:53). Most Muslims do not worship idols at all, and having a job or enjoying possessions is not shirk unless they replace God. Zakah keeps wealth in its proper place by reminding Muslims that it belongs ultimately to God.\n\nCONCLUSION\nObvious shirk such as idol worship is easy for most British Muslims to avoid, but subtle forms, such as letting wealth or status matter more than God, are genuinely challenging in a materialistic culture. However, practices like salah and zakah are designed to meet that challenge. I conclude that avoiding shirk requires real effort today but is not unusually difficult, because Islam gives clear guidance and regular habits that help.","evidence":["Qur'an 4:48","Qur'an 39:53","Hadith on riya' (minor shirk), Musnad Ahmad","Allahu Akbar"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"shirk today"},{"id":"aqa-rs-a-islam-paper1-1-3-0","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","question":"Which word means that God is beyond and outside the created universe?\nA Immanent\nB Transcendent\nC Beneficent\nD Omnipotent","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Transcendent means God is beyond the world and human understanding; immanent is the opposite idea of God being close and active within the world.","evidence":["Qur'an 6:103","Qur'an 42:11"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"transcendence"},{"id":"aqa-rs-a-islam-paper1-1-3-1","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","question":"What does the Shi'a term 'Adalat' refer to?\nA God's mercy\nB God's justice\nC God's power\nD God's oneness","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Adalat is the Shi'a root of faith stating that God is perfectly just and never acts unfairly.","evidence":["Qur'an 4:40"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Adalat"},{"id":"aqa-rs-a-islam-paper1-1-3-2","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","question":"Give two of the names or qualities of Allah.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: ar-Rahman (the Most Gracious / Beneficent); ar-Rahim (the Most Merciful); al-Adl (the Just); al-Qadir (the All-Powerful / omnipotent); al-Alim (the All-Knowing); al-Khaliq (the Creator); al-Ghaffar (the Forgiving). Accept English qualities such as merciful, just, omnipotent, beneficent.","evidence":["The 99 Names of Allah (al-Asma' al-Husna)"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"names of God"},{"id":"aqa-rs-a-islam-paper1-1-3-3","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","question":"Give two ways Muslims believe God shows His beneficence.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: creating the world and everything humans need; giving life and the natural world (food, water, rain); sending prophets and holy books for guidance; giving humans intelligence and free will; providing for every creature; offering forgiveness.","evidence":["Ar-Rahman","Qur'an 55 (Surah ar-Rahman)"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"beneficence"},{"id":"aqa-rs-a-islam-paper1-1-3-4","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","question":"Explain two contrasting Muslim beliefs about God's relationship with the world.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. God is transcendent: He is beyond the universe, outside time and space, and cannot be fully understood or pictured. 'Vision perceives Him not' (6:103). This is why Muslims never make images of God and use names rather than descriptions.\n\n2. God is also immanent: He is close to every person and involved in the world. The Qur'an says 'We are closer to him than his jugular vein' (50:16). Muslims therefore believe God hears every private prayer (du'a) and knows their thoughts, so He can be approached directly at any time.","evidence":["Qur'an 6:103","Qur'an 50:16"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"immanence and transcendence"},{"id":"aqa-rs-a-islam-paper1-1-3-5","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","question":"Explain two ways belief that God is merciful influences Muslims.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It encourages Muslims to repent and not give up. Because God is ar-Rahim, Muslims believe that sincere repentance (tawbah) brings forgiveness, so a person who has done wrong is motivated to change rather than despair, e.g. by asking forgiveness in prayer during Ramadan.\n\n2. It encourages them to be merciful to others. Nearly every surah starts 'In the name of Allah, the Most Gracious, the Most Merciful', and Muslims are taught to imitate God's mercy by forgiving people and helping those in need, for example through zakah, sadaqah or volunteering at food banks.","evidence":["Bismillah ar-Rahman ar-Rahim","Tawbah"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"mercy"},{"id":"aqa-rs-a-islam-paper1-1-3-6","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","question":"Explain two Muslim beliefs about the nature of God.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. God is omnipotent (all-powerful). The Qur'an repeats that 'Allah is over all things competent' (Qur'an 2:20). Muslims believe God created the universe simply by commanding 'Be' (kun) and it was, so nothing is beyond His power, and believers can trust Him in every situation.\n\n2. God is merciful. Each surah except one begins 'In the name of Allah, the Most Gracious, the Most Merciful', and in a hadith qudsi God says 'My mercy prevails over My wrath' (Bukhari and Muslim). This means Muslims see God not only as a judge but as loving and forgiving, which gives them hope.","evidence":["Qur'an 2:20","Qur'an 36:82 ('Be, and it is')","Hadith qudsi: 'My mercy prevails over My wrath'"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"nature of God"},{"id":"aqa-rs-a-islam-paper1-1-3-7","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","question":"Explain two reasons why belief in God's justice (Adalat) is important to Shi'a Muslims.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It guarantees that judgement will be fair. 'Indeed, Allah does not do injustice, even as much as an atom's weight' (Qur'an 4:40). Shi'as believe this means God would never punish people for actions they were forced into, so humans must have genuine free will and are responsible for their choices.\n\n2. It inspires Muslims to work for justice in the world. Since God is just, His followers must be too: 'O you who believe, be persistently standing firm for Allah, witnesses in justice' (Qur'an 5:8). For many Shi'as, Imam Husayn's stand against the unjust ruler Yazid at Karbala is the supreme example, encouraging them to stand up against oppression today.","evidence":["Qur'an 4:40","Qur'an 5:8","Karbala (680 CE)"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"Adalat"},{"id":"aqa-rs-a-islam-paper1-1-3-8","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","question":"‘God cannot be both merciful and just.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nSome people argue there is a tension between mercy and justice. Justice means giving people exactly what they deserve - punishing wrongdoing and rewarding good. Mercy means letting people off what they deserve. If God forgives a murderer who repents, it may seem unfair to the victim; if He always punishes, He would not be merciful. Critics, including some atheists, also ask how a just and merciful God could allow so much suffering of innocent people, for example in natural disasters, and conclude that He cannot have both qualities perfectly.\n\nThe Qur'an describes both Jannah and Jahannam, and some people find it hard to see eternal punishment as merciful, or forgiveness of serious crimes as just.\n\nARGUMENTS AGAINST THE STATEMENT\nMuslims believe God is both, and the Qur'an presents them together. God is al-Adl (the Just): 'Allah does not do injustice, even as much as an atom's weight' (4:40). God is also ar-Rahman and ar-Rahim, and 'My mercy encompasses all things' (7:156). Muslims argue that God's mercy works within His justice: He offers forgiveness to those who sincerely repent, which is fair because everyone is offered the same chance. A hadith qudsi says 'My mercy prevails over My wrath', which suggests mercy is the greater quality but does not cancel justice.\n\nShi'a Muslims stress Adalat as a root of faith, and argue that because God is just He gives humans free will and never punishes anyone for something they could not avoid. Mercy is shown in His giving guidance through prophets and Imams, so people are not judged without being warned. Also, only God knows everything about a person's circumstances, so He can judge with perfect justice while taking into account what humans cannot see, such as intentions (niyyah). Suffering in this life may be a test (2:155), with reward in the hereafter, which balances out what seems unfair now.\n\nCONCLUSION\nThe objection works if justice and mercy are understood in purely human, legal terms. However, Islam teaches that God's knowledge is complete and that He sets fair conditions for mercy - repentance and faith - which apply to everyone. Since a perfectly wise judge could combine strict fairness with generous forgiveness, I conclude that the statement is not convincing: God can be both merciful and just, although the problem of suffering remains a serious challenge for believers to think through.","evidence":["Qur'an 4:40","Qur'an 7:156","Qur'an 2:155","Hadith qudsi on mercy","Adalat"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"mercy and justice"},{"id":"aqa-rs-a-islam-paper1-1-3-9","paper":"Beliefs","module":"1.3","moduleTitle":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","question":"‘It is impossible for God to be both immanent and transcendent.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nAt first these two ideas seem to contradict each other. Transcendence means God is beyond the universe, outside time and space and completely unlike anything created: 'There is nothing like unto Him' (42:11) and 'Vision perceives Him not' (6:103). Immanence means God is present within the world and close to people. Some argue that if God is wholly 'other' and beyond creation, He cannot also be inside it in a personal way, and if He is close and involved, He is no longer completely beyond.\n\nA non-religious thinker might add that both claims are untestable, so describing God as both just shows that the concept is incoherent.\n\nARGUMENTS AGAINST THE STATEMENT\nMuslims believe the Qur'an teaches both, so they must be compatible. 'We are closer to him than his jugular vein' (50:16) expresses immanence, and 'He is the First and the Last, the Outward and the Inward' (57:3) shows both together. Many scholars explain that God is transcendent in His essence - what He is - but immanent in His knowledge, power and care. Being outside creation does not stop Him knowing and sustaining every part of it, just as an author is not a character in a book but knows every word of it.\n\nMuslims experience both: God's transcendence explains why they do not picture Him and why He is worthy of total worship; His immanence explains why they can make personal du'a at any time and believe He answers: 'I am near; I respond to the call of the caller when he calls on Me' (2:186). Sufi Muslims especially emphasise closeness to God through dhikr (remembrance), while still affirming His transcendence. If God is all-powerful, it would be strange to say He is unable to be close to His creation.\n\nCONCLUSION\nThe two ideas would contradict each other if they described God in the same way at the same time. But Islam teaches that God is beyond the world in His being and close to it in His knowledge and care. This gives a coherent picture of a God who is both worthy of awe and approachable, so I disagree with the statement: it is possible, and important for Muslims, that God is both immanent and transcendent.","evidence":["Qur'an 42:11","Qur'an 6:103","Qur'an 50:16","Qur'an 57:3","Qur'an 2:186"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"immanence and transcendence"},{"id":"aqa-rs-a-islam-paper1-1-4-0","paper":"Beliefs","module":"1.4","moduleTitle":"Angels, their nature and role, including Jibril and Mika'il","question":"Which angel brought the revelation of the Qur'an to the Prophet Muhammad?\nA Mika'il\nB Israfil\nC Jibril\nD Izra'il","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C - Jibril (Gabriel) delivered God's revelation to Muhammad, beginning in the Cave of Hira in 610 CE.","evidence":["Qur'an 2:97","Qur'an 96:1-5"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Jibril"},{"id":"aqa-rs-a-islam-paper1-1-4-1","paper":"Beliefs","module":"1.4","moduleTitle":"Angels, their nature and role, including Jibril and Mika'il","question":"According to Islamic tradition, what are angels created from?\nA Clay\nB Smokeless fire\nC Light\nD Water","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C - A hadith in Sahih Muslim says angels were created from light, jinn from smokeless fire and Adam from clay.","evidence":["Sahih Muslim (Book of Zuhd)"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"nature of angels"},{"id":"aqa-rs-a-islam-paper1-1-4-2","paper":"Beliefs","module":"1.4","moduleTitle":"Angels, their nature and role, including Jibril and Mika'il","question":"Give two roles of angels in Islam.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: bringing God's messages to prophets (Jibril); providing nourishment and rain (Mika'il); recording people's good and bad deeds (Kiraman Katibin); taking souls at death (Malak al-Mawt / Izra'il); questioning souls in the grave (Munkar and Nakir); blowing the trumpet on the Day of Judgement (Israfil); guarding heaven and hell; praising and worshipping God.","evidence":["Qur'an 82:10-12","Qur'an 32:11"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"roles of angels"},{"id":"aqa-rs-a-islam-paper1-1-4-3","paper":"Beliefs","module":"1.4","moduleTitle":"Angels, their nature and role, including Jibril and Mika'il","question":"Give two beliefs about the nature of angels in Islam.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: they are made of light; they have no free will and always obey God; they do not eat, drink or have gender in a human sense; they are usually invisible but can take human form; they are immortal servants of God; they constantly worship God.","evidence":["Qur'an 66:6"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"nature of angels"},{"id":"aqa-rs-a-islam-paper1-1-4-4","paper":"Beliefs","module":"1.4","moduleTitle":"Angels, their nature and role, including Jibril and Mika'il","question":"Explain two ways belief in angels influences Muslims today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Knowing that angels (Kiraman Katibin) record every deed encourages Muslims to behave well even when no other person can see them, e.g. being honest in exams or at work, because their 'book' of deeds will be shown on the Day of Judgement.\n\n2. It strengthens trust in the Qur'an and the prophets. Because Jibril delivered God's words exactly, Muslims believe the Qur'an is God's direct revelation and so follow its teaching carefully, for example memorising it and reciting it in salah. Some Muslims end prayer by turning their head right and left to greet the recording angels, which reminds them that angels are always present.","evidence":["Kiraman Katibin (82:10-12)","Jibril and revelation"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"influence"},{"id":"aqa-rs-a-islam-paper1-1-4-5","paper":"Beliefs","module":"1.4","moduleTitle":"Angels, their nature and role, including Jibril and Mika'il","question":"Explain two differences between angels and humans in Islam.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Angels have no free will, but humans do. Angels 'do not disobey Allah in what He commands them' (66:6), while humans can choose good or evil, which is why only humans (and jinn) will be judged and rewarded or punished.\n\n2. Angels are created from light, while humans were created from clay. Because angels are pure spiritual beings who do not eat, sleep or have physical desires, they can worship God continuously, whereas humans must struggle against temptation; this is why the Qur'an tells of angels bowing to Adam, showing the special status God gave humans as khalifah despite their weakness.","evidence":["Qur'an 66:6","Qur'an 2:30-34"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"angels and humans"},{"id":"aqa-rs-a-islam-paper1-1-4-6","paper":"Beliefs","module":"1.4","moduleTitle":"Angels, their nature and role, including Jibril and Mika'il","question":"Explain two reasons why angels are important in Islam.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. They are the link between God and the prophets. Jibril brought the Qur'an to Muhammad: 'Whoever is an enemy to Jibril - it is he who has brought it [the Qur'an] down upon your heart by permission of Allah' (Qur'an 2:97). Without angels there would be no revelation, so belief in them is necessary to accept the Qur'an as God's word.\n\n2. They carry out God's will in the world and in the afterlife. Mika'il is believed to be responsible for nourishment and rain, the Angel of Death 'will take you' at the appointed time (Qur'an 32:11), and Israfil will blow the trumpet to begin the Day of Judgement. This reminds Muslims that God's care and judgement are active in every part of life and death.","evidence":["Qur'an 2:97","Qur'an 32:11","Qur'an 2:98 (Jibril and Mika'il)"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"importance of angels"},{"id":"aqa-rs-a-islam-paper1-1-4-7","paper":"Beliefs","module":"1.4","moduleTitle":"Angels, their nature and role, including Jibril and Mika'il","question":"Explain two Muslim beliefs about Jibril and Mika'il.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Jibril is the angel of revelation. He appeared to Muhammad in the Cave of Hira on the Night of Power in 610 CE and commanded 'Read! (Iqra) In the name of your Lord who created' (Qur'an 96:1). He continued to bring the Qur'an over about 23 years and is also believed to have accompanied the Prophet on the Night Journey (al-Isra' wal-Mi'raj).\n\n2. Mika'il is the angel of mercy and provision, believed to send rain and nourishment to the earth and plants by God's command. He is named alongside Jibril in Qur'an 2:98, which warns that being an enemy of God's angels, 'Jibril and Mika'il', is being an enemy of God. This shows that Muslims see both as great angels close to God whose work shows His care for creation.","evidence":["Qur'an 96:1","Qur'an 2:98","Night Journey (Qur'an 17:1)"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"Jibril and Mika'il"},{"id":"aqa-rs-a-islam-paper1-1-4-8","paper":"Beliefs","module":"1.4","moduleTitle":"Angels, their nature and role, including Jibril and Mika'il","question":"‘Belief in angels is not important for Muslims today.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nSome might argue that angels belong to the past. Their best-known work - bringing the Qur'an to Muhammad - finished with the Prophet's death in 632 CE, and Muslims now have the Qur'an itself to guide them. Angels are invisible and their existence cannot be proved scientifically, so a non-religious person, or even some modern Muslims, may see them as less relevant than practical duties such as prayer, charity and family life. The Qur'an rarely gives detail about angels, and much of what is said about figures such as Israfil comes from later hadith tradition.\n\nARGUMENTS AGAINST THE STATEMENT\nBelief in angels is one of the six articles of faith; the Qur'an says that whoever disbelieves in 'His angels' has 'gone far astray' (4:136). So for Sunni Muslims it is a required belief, not an optional extra. Although Shi'a Muslims do not list it among the five roots of Usul ad-Din, they also accept it as part of belief in Nubuwwah and the Qur'an.\n\nAngels are important today in several ways. The Kiraman Katibin 'know whatever you do' (82:10-12), so Muslims are reminded that every action is being recorded, which encourages honesty and self-discipline. The Angel of Death and the questioning angels Munkar and Nakir remind Muslims to prepare for death and the afterlife. Many Muslims feel comforted by angels: the Qur'an speaks of angels descending on the Night of Power (97:4) and supporting believers (41:30). Belief in Jibril underlies the authority of the Qur'an, which Muslims recite every day, so the angel's role continues to matter whenever the Qur'an is read.\n\nCONCLUSION\nIt is true that angels do not appear in everyday life in the way prayer or fasting does, and that their existence cannot be proven. However, for Muslims they are part of God's revealed truth, they guarantee the reliability of the Qur'an, and the belief that deeds are recorded has a clear daily effect on behaviour. I therefore disagree with the statement: belief in angels remains important for Muslims today, even if its importance is often felt indirectly.","evidence":["Qur'an 4:136","Qur'an 82:10-12","Qur'an 97:4","Qur'an 41:30"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"angels today"},{"id":"aqa-rs-a-islam-paper1-1-4-9","paper":"Beliefs","module":"1.4","moduleTitle":"Angels, their nature and role, including Jibril and Mika'il","question":"‘Jibril is the most important angel.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nJibril is the angel of revelation. He brought the Qur'an to Muhammad over 23 years, beginning in the Cave of Hira with the command 'Read!' (96:1), and Muslims believe the Qur'an is the final and complete word of God. Without Jibril, humanity would not have received this guidance. He is also believed to have brought revelation to earlier prophets, appeared in the Hadith of Jibril to teach the basics of Islam, Iman and Ihsan, and accompanied the Prophet on the Night Journey, during which the five daily prayers were given. The Qur'an calls him 'the trustworthy spirit' (26:193) and the 'Holy Spirit' (Ruh al-Qudus, 16:102). Many Muslims would therefore see him as the greatest of the angels.\n\nARGUMENTS AGAINST THE STATEMENT\nOthers argue that all angels simply do God's will and that ranking them is not helpful; all of them 'do not disobey Allah' (66:6), so their importance comes from God, not from themselves. Mika'il is named alongside Jibril (2:98) and is responsible for provision and mercy, which every living thing depends on. Israfil will blow the trumpet to begin the resurrection, and the Angel of Death takes every soul; for an ordinary Muslim's daily life and future, the recording angels (Kiraman Katibin) and the questioning angels in the grave may be more directly relevant, because they relate to each person's own judgement.\n\nA non-religious person may argue that none is important because there is no evidence that angels exist, although this does not tell us how Muslims rank them.\n\nCONCLUSION\nAll angels serve God and each role is necessary, so in one sense none is 'more important' in itself. However, Jibril's role in delivering revelation is unique - it is the source of the Qur'an and Sunnah on which all Muslim belief and practice depend. Weighing this, I agree that Jibril is the most important angel for Muslims, while recognising that his importance comes entirely from the message he carried from God.","evidence":["Qur'an 96:1","Qur'an 26:193","Qur'an 16:102","Qur'an 2:98","Qur'an 66:6"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Jibril"},{"id":"aqa-rs-a-islam-paper1-1-5-0","paper":"Beliefs","module":"1.5","moduleTitle":"Predestination and human freedom and its relationship to the Day of Judgement","question":"What is the Arabic term for the belief that Allah has decreed all things?\nA Al-Qadr\nB Akhirah\nC Barzakh\nD Ihram","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"A - Al-Qadr (divine decree / predestination) is the sixth Sunni article of faith; Akhirah is life after death, barzakh the state between death and resurrection, ihram the state of purity on Hajj.","evidence":["Qur'an 54:49"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"al-Qadr"},{"id":"aqa-rs-a-islam-paper1-1-5-1","paper":"Beliefs","module":"1.5","moduleTitle":"Predestination and human freedom and its relationship to the Day of Judgement","question":"What does the phrase 'Insha'Allah' mean?\nA God is greatest\nB If God wills\nC Praise be to God\nD In the name of God","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Muslims say 'Insha'Allah' about future plans to show that everything happens only by God's will (Qur'an 18:23-24).","evidence":["Qur'an 18:23-24"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Insha'Allah"},{"id":"aqa-rs-a-islam-paper1-1-5-2","paper":"Beliefs","module":"1.5","moduleTitle":"Predestination and human freedom and its relationship to the Day of Judgement","question":"Give two Muslim beliefs about predestination.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: God knows everything that has happened and will happen; everything is written in the Preserved Tablet (al-Lawh al-Mahfuz); nothing happens without God's permission; God created everything with a measure / plan (54:49); humans are still responsible for their choices; Shi'as stress that God's foreknowledge does not force human actions.","evidence":["Qur'an 54:49","Al-Lawh al-Mahfuz (85:21-22)"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"predestination"},{"id":"aqa-rs-a-islam-paper1-1-5-3","paper":"Beliefs","module":"1.5","moduleTitle":"Predestination and human freedom and its relationship to the Day of Judgement","question":"Give two ways belief in predestination affects how a Muslim lives.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: saying 'Insha'Allah' about future plans; accepting hardship patiently (sabr); trusting in God (tawakkul); not becoming arrogant about success because it comes from God; making du'a, believing God can respond; still working hard and making good choices because they will be judged.","evidence":["Sabr","Tawakkul"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"influence"},{"id":"aqa-rs-a-islam-paper1-1-5-4","paper":"Beliefs","module":"1.5","moduleTitle":"Predestination and human freedom and its relationship to the Day of Judgement","question":"Explain two contrasting Muslim beliefs about predestination and human freedom.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Many Sunni Muslims emphasise God's complete control. Following the Ash'ari tradition, they believe God wills and creates all events, including human actions, which are recorded in al-Lawh al-Mahfuz, while humans 'acquire' responsibility for what they choose. God's knowledge and power cannot be limited.\n\n2. Shi'a Muslims (and earlier the Mu'tazila) emphasise human freedom because of Adalat. God knows what people will do, but He does not cause their sins; it would be unjust to predetermine someone's evil and then punish them. So humans freely choose their actions, and God's knowledge is like knowing the outcome rather than forcing it.","evidence":["Al-Lawh al-Mahfuz","Adalat","Ash'ari and Mu'tazila schools"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"Sunni and Shi'a views"},{"id":"aqa-rs-a-islam-paper1-1-5-5","paper":"Beliefs","module":"1.5","moduleTitle":"Predestination and human freedom and its relationship to the Day of Judgement","question":"Explain two ways belief in al-Qadr influences Muslims today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It helps them cope with suffering. If a Muslim loses a job or a family member, belief that this is within God's plan helps them respond with patience (sabr) and trust that there may be a purpose they cannot see, rather than despair.\n\n2. It keeps them humble about success. Muslims say 'Alhamdulillah' (praise be to God) after achievements, such as good exam results, recognising that ability and opportunity come from God. They also say 'Insha'Allah' about future plans because they cannot control what will happen, but they still prepare fully, following the hadith 'Tie your camel, then trust in God'.","evidence":["Sabr","Hadith: 'Tie your camel and trust in Allah' (Tirmidhi)"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"influence"},{"id":"aqa-rs-a-islam-paper1-1-5-6","paper":"Beliefs","module":"1.5","moduleTitle":"Predestination and human freedom and its relationship to the Day of Judgement","question":"Explain two Muslim teachings about the relationship between predestination and the Day of Judgement.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Humans are judged on their own choices, so they must be free in a meaningful way. The Qur'an says 'the truth is from your Lord, so whoever wills - let him believe; and whoever wills - let him disbelieve' (Qur'an 18:29). God's decree does not remove responsibility; people will be held accountable for what they chose to do.\n\n2. God's foreknowledge means judgement will be perfectly fair and complete. Everything is recorded in the Preserved Tablet (al-Lawh al-Mahfuz) and by the recording angels, and nothing is hidden from God. Shi'as stress, through Adalat, that God would never punish someone for what they were forced to do, so judgement depends on intentions and actions freely chosen.","evidence":["Qur'an 18:29","Qur'an 85:22 (Preserved Tablet)","Adalat"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"predestination and judgement"},{"id":"aqa-rs-a-islam-paper1-1-5-7","paper":"Beliefs","module":"1.5","moduleTitle":"Predestination and human freedom and its relationship to the Day of Judgement","question":"Explain two Muslim beliefs about human freedom.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. God has given humans free will so that they can be tested. 'It is He who created death and life to test you as to which of you is best in deed' (Qur'an 67:2). A test would only be meaningful if people can genuinely choose, so Muslims believe they are free to obey or disobey.\n\n2. Humans can change their situation through their choices. 'Indeed, Allah will not change the condition of a people until they change what is in themselves' (Qur'an 13:11). This encourages Muslims to take responsibility, work hard, repent and improve, rather than passively accepting whatever happens as fate.","evidence":["Qur'an 67:2","Qur'an 13:11"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"free will"},{"id":"aqa-rs-a-islam-paper1-1-5-8","paper":"Beliefs","module":"1.5","moduleTitle":"Predestination and human freedom and its relationship to the Day of Judgement","question":"‘If God has already decided everything, it is unfair to judge people.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nThe Qur'an says 'Indeed, all things We created with predestination' (54:49), and Sunni Muslims believe in al-Qadr as one of the six articles of faith: everything is recorded in the Preserved Tablet before it happens. If God already knows and has decreed that a person will commit a sin, it seems that person could not have done otherwise. Judging and punishing someone for an action they could not avoid would be unjust, like punishing a robot for following its programming. Atheists and some philosophers see this as a contradiction between an all-powerful God and a fair judge.\n\nARGUMENTS AGAINST THE STATEMENT\nMuslims answer that the Qur'an teaches both God's decree and human responsibility. 'Whoever wills - let him believe; and whoever wills - let him disbelieve' (18:29) shows that people really choose. Many Sunni scholars (the Ash'ari tradition) say God creates actions but humans 'acquire' them through their choice, so they are responsible. Knowing what someone will do is not the same as forcing them; a teacher may predict a student will not revise, but the student still chooses.\n\nShi'a Muslims stress Adalat (justice) as a root of faith: because God is perfectly just, He does not compel anyone to sin. 'Allah does not do injustice, even as much as an atom's weight' (4:40). God judges people on their niyyah (intentions) and circumstances, and is merciful to those who repent, so judgement is fair. Life is described as a test (67:2), and a test only makes sense if there is freedom. Moreover, the Qur'an says God will not burden a soul beyond what it can bear (2:286), showing that people are judged according to their real abilities.\n\nCONCLUSION\nThe statement would be correct if predestination meant that God forces every action. However, most Muslims understand al-Qadr as God's complete knowledge and permission, not compulsion, and the Qur'an clearly affirms human choice and God's justice. Although the relationship remains a mystery that humans cannot fully grasp, I conclude that judgement is not unfair, because people are held responsible only for what they freely chose and intended.","evidence":["Qur'an 54:49","Qur'an 18:29","Qur'an 4:40","Qur'an 67:2","Qur'an 2:286"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"predestination and judgement"},{"id":"aqa-rs-a-islam-paper1-1-5-9","paper":"Beliefs","module":"1.5","moduleTitle":"Predestination and human freedom and its relationship to the Day of Judgement","question":"‘Belief in predestination makes it pointless for Muslims to try to improve their lives.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nIf everything has been decided by God in advance and written in al-Lawh al-Mahfuz, some might think there is no point in effort. Whether a person passes an exam, recovers from illness or becomes rich has already been decreed, so working hard or taking medicine seems pointless. This kind of fatalism has sometimes been seen in history, and critics of religion argue that belief in fate can lead people to accept injustice or poverty instead of changing things.\n\nARGUMENTS AGAINST THE STATEMENT\nMost Muslims strongly reject fatalism. The Qur'an teaches 'Allah will not change the condition of a people until they change what is in themselves' (13:11), which means human effort is part of how God's plan works. The Prophet told a man who left his camel untied 'Tie it and trust in Allah' (Tirmidhi), showing that Muslims should both act responsibly and trust God. The Prophet himself planned carefully, for example before the Hijrah to Madinah in 622 CE, and encouraged seeking medical treatment: 'Allah has not sent down any disease without also sending down a cure' (Bukhari).\n\nBecause humans do not know what has been decreed, they must act as if their choices matter - which they do, since they will be judged on them (18:29; 99:7-8). Shi'a Muslims' emphasis on Adalat and free will gives an even stronger reason to strive. Islam also teaches that du'a (personal prayer) can be answered, which would make no sense if effort and prayer changed nothing. Many Muslims say belief in al-Qadr actually helps them try, because it removes the fear of failure: they do their best and accept the result with sabr.\n\nCONCLUSION\nA distorted idea of predestination could lead to passivity, but this is not what Islam teaches. The Qur'an and Hadith combine trust in God's plan with a duty to act and improve, and judgement is based on effort and intention. I therefore disagree with the statement: belief in predestination gives Muslims a reason to try hard and accept outcomes calmly, rather than making effort pointless.","evidence":["Qur'an 13:11","Hadith: 'Tie your camel'","Hadith on cures (Bukhari)","Qur'an 18:29","Qur'an 99:7-8"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"fatalism"},{"id":"aqa-rs-a-islam-paper1-1-6-0","paper":"Beliefs","module":"1.6","moduleTitle":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","question":"What is barzakh?\nA The bridge over hell\nB The state or place between death and the Day of Judgement\nC The highest level of paradise\nD The book of a person's deeds","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Barzakh ('barrier') is the waiting state between death and resurrection (Qur'an 23:100). The bridge is as-Sirat; the highest level of paradise is often called al-Firdaws.","evidence":["Qur'an 23:100"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"barzakh"},{"id":"aqa-rs-a-islam-paper1-1-6-1","paper":"Beliefs","module":"1.6","moduleTitle":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","question":"Which Arabic term refers to hell in Islam?\nA Jannah\nB Jahannam\nC Jihad\nD Jummah","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Jahannam is hell; Jannah is paradise, jihad means striving and Jummah is Friday prayer.","evidence":["Qur'an 4:56"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"hell"},{"id":"aqa-rs-a-islam-paper1-1-6-2","paper":"Beliefs","module":"1.6","moduleTitle":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","question":"Give two Muslim beliefs about Jannah (paradise).","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: it is a garden of peace and beauty (Qur'an 47:15 describes rivers of water, milk, honey and pure drink); it is the reward for those who believed and did good; there are levels, the highest being al-Firdaws; people will be with their families and loved ones; there is no pain, sadness or tiredness; the greatest reward is being close to God / seeing God.","evidence":["Qur'an 47:15","Qur'an 15:47-48"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"Jannah"},{"id":"aqa-rs-a-islam-paper1-1-6-3","paper":"Beliefs","module":"1.6","moduleTitle":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","question":"Give two things Muslims believe will happen on the Day of Judgement.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: Israfil will blow the trumpet; all people will be resurrected bodily; everyone's deeds will be weighed in the balance (mizan); each person will receive the book of their deeds in their right or left hand; people will cross the bridge as-Sirat; people will be sent to Jannah or Jahannam; the Prophet will intercede (shafa'ah) for believers.","evidence":["Qur'an 69:19-25","Qur'an 101:6-9"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"Day of Judgement"},{"id":"aqa-rs-a-islam-paper1-1-6-4","paper":"Beliefs","module":"1.6","moduleTitle":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","question":"Explain two ways belief in Akhirah influences Muslims today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It motivates good behaviour. Knowing they will be held accountable for every deed, Muslims try to be honest, keep promises and help others - for example giving zakah and sadaqah, or volunteering - because these good deeds will weigh in their favour.\n\n2. It affects how they face death and grief. Muslims see death as a passage to the next life rather than the end, so they bury the dead quickly, facing Makkah, and pray the janazah prayer for the person's forgiveness. Mourners are comforted by the hope of meeting again in Jannah, and they say 'To Allah we belong and to Him we return' (2:156).","evidence":["Qur'an 2:156","Janazah prayer"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"influence"},{"id":"aqa-rs-a-islam-paper1-1-6-5","paper":"Beliefs","module":"1.6","moduleTitle":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","question":"Explain two Muslim beliefs about human responsibility and accountability.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Humans are God's khalifah (stewards) on earth (2:30) and are responsible for how they treat the world and other people. They have been given intelligence and free will, so they cannot blame others or fate for their wrong choices.\n\n2. Every person is individually accountable. 'No bearer of burdens will bear the burden of another' (35:18), so nobody can be punished or saved because of someone else. On the Day of Judgement every deed, even 'an atom's weight', will be shown (99:7-8), so Muslims believe they must answer personally for their actions and intentions.","evidence":["Qur'an 2:30","Qur'an 35:18","Qur'an 99:7-8"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"accountability"},{"id":"aqa-rs-a-islam-paper1-1-6-6","paper":"Beliefs","module":"1.6","moduleTitle":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","question":"Explain two Muslim beliefs about the resurrection and the Day of Judgement.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. All people will be physically resurrected. The Qur'an answers those who doubt by saying the One who created them the first time can bring them back: 'He will give life to them who produced them the first time' (Qur'an 36:79). Muslims therefore usually bury bodies rather than cremating them, out of respect for the body that will be raised.\n\n2. Each person will be judged and given their record of deeds. 'As for he who is given his record in his right hand, he will say, \"Here, read my record!\"' while the one given it in his left hand will wish he had never received it (Qur'an 69:19-25). Deeds will be weighed on the scales (mizan) and people sent to Jannah or Jahannam, though God's mercy and the Prophet's intercession can help believers.","evidence":["Qur'an 36:79","Qur'an 69:19-25","Qur'an 101:6-9"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"resurrection and judgement"},{"id":"aqa-rs-a-islam-paper1-1-6-7","paper":"Beliefs","module":"1.6","moduleTitle":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","question":"Explain two Muslim beliefs about heaven and hell.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Jannah (paradise) is a garden of eternal peace for those who believed and did good. The Qur'an describes 'rivers of water unaltered, rivers of milk... rivers of wine delicious to drinkers, and rivers of purified honey' (Qur'an 47:15). Many Muslims understand these descriptions as real, while others see them as symbols of joy beyond human imagination; the greatest reward is closeness to God.\n\n2. Jahannam (hell) is a place of punishment for those who rejected God and did evil without repenting. It is described as fire whose 'fuel is people and stones' (Qur'an 66:6). Some scholars believe that sinful Muslims may be purified there for a time before entering paradise, while it is eternal for those who rejected God entirely; this shows both God's justice and His mercy.","evidence":["Qur'an 47:15","Qur'an 66:6","Qur'an 9:72"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"heaven and hell"},{"id":"aqa-rs-a-islam-paper1-1-6-8","paper":"Beliefs","module":"1.6","moduleTitle":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","question":"‘Belief in life after death is the most important influence on how a Muslim lives.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nBelief in Akhirah gives every action eternal consequences. 'Whoever does an atom's weight of good will see it, and whoever does an atom's weight of evil will see it' (99:7-8). Because Muslims believe their deeds are being recorded by the Kiraman Katibin and will be weighed on the Day of Judgement, this belief can shape decisions about honesty, money, relationships and worship. The Qur'an describes this world as temporary and the next life as 'better and more lasting' (87:17). Belief in Akhirah also explains why Muslims fast in Ramadan, give zakah and avoid haram things: these choices are an investment in the hereafter. It shapes Muslim funerals, attitudes to grief and the hope that gives comfort in suffering.\n\nARGUMENTS AGAINST THE STATEMENT\nMany Muslims argue that Tawhid and love of God are more important influences than hope of reward or fear of punishment. The ideal is to worship God because He deserves it; the Sufi saint Rabi'a al-Adawiyya famously prayed that she would worship God out of love, not fear of hell or desire for paradise. Ihsan, described in the Hadith of Jibril as worshipping God 'as if you see Him', suggests the main motive should be awareness of God now, not the afterlife.\n\nOther influences are also powerful in daily life: the example (Sunnah) of the Prophet Muhammad, the Qur'an's direct commands, family and community (the ummah), and, for Shi'as, the guidance of the Imams and the marja'. A non-religious person would point out that people of all beliefs live morally because of empathy and conscience, not reward. Some Muslims might also say that living for this world properly - caring for others, acting as khalifah - is valuable in itself.\n\nCONCLUSION\nBelief in Akhirah is clearly a powerful motivator, giving Muslims a reason to act well even when no one is watching. However, Akhirah depends on Tawhid: it is God who judges, and the best reason to act well is love and obedience to God. I therefore think the statement goes too far - belief in life after death is one of the most important influences, but the deepest influence is belief in God Himself, with Akhirah as one consequence of that belief.","evidence":["Qur'an 99:7-8","Qur'an 87:17","Hadith of Jibril (ihsan)","Rabi'a al-Adawiyya"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Akhirah"},{"id":"aqa-rs-a-islam-paper1-1-6-9","paper":"Beliefs","module":"1.6","moduleTitle":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","question":"‘A loving God would not send anyone to hell.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nIslam teaches that God is ar-Rahman and ar-Rahim, and that 'My mercy encompasses all things' (7:156). Some people argue that a God of infinite mercy would forgive everyone eventually, and that eternal punishment for sins committed in a short human life seems out of proportion. Many people also make wrong choices because of their upbringing, ignorance or suffering. Non-religious people, and some religious believers, argue that the idea of hell is a way of controlling behaviour through fear and is incompatible with a loving God.\n\nThere is also diversity within Islam: some scholars, including the medieval thinker Ibn Qayyim al-Jawziyya, discussed whether hell's punishment might eventually end, and many Muslims believe sinful believers will only be in hell temporarily before being brought into paradise.\n\nARGUMENTS AGAINST THE STATEMENT\nMost Muslims believe hell is real because the Qur'an clearly describes it (e.g. 4:56, 66:6) and God is also al-Adl, the Just. A God who never held anyone to account for murder, cruelty or oppression would not be just to the victims. Justice and mercy go together: God offers mercy to anyone who sincerely repents (39:53), sends prophets and books so no one is punished without warning (17:15), and judges according to intentions and circumstances. Those who go to hell have, in a sense, chosen to reject God's repeated offers of mercy, using the free will He gave them.\n\nShi'a Muslims, stressing Adalat, argue that God's justice means no one is punished unfairly; hell is not a sign of a lack of love but of taking human choices seriously. Love that ignored evil would not be genuine love. Many hadiths emphasise that God's mercy is vast, that the Prophet will intercede for believers, and that anyone with 'an atom's weight of faith' will eventually leave the Fire (Bukhari), showing hell is not God's desire but a consequence of persistent wrongdoing.\n\nCONCLUSION\nThe statement raises a fair question about proportion and love. However, Islam presents God as both perfectly loving and perfectly just, and a just God must take evil seriously. Since everyone is offered mercy and guidance, and many believe hell is purifying for some, I conclude that a loving God could allow hell, so I disagree with the statement - although Muslims hope and pray that God's mercy will reach as many as possible.","evidence":["Qur'an 7:156","Qur'an 4:56","Qur'an 17:15","Qur'an 39:53","Hadith on intercession and leaving the Fire (Bukhari)"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"heaven and hell"},{"id":"aqa-rs-a-islam-paper1-1-7-0","paper":"Beliefs","module":"1.7","moduleTitle":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","question":"Which title does the Qur'an give to Muhammad in Surah 33:40?\nA Friend of God\nB Seal of the Prophets\nC Father of the prophets\nD Spirit of God","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Qur'an 33:40 calls Muhammad 'the Messenger of Allah and the Seal (khatam) of the Prophets', meaning he is the final prophet.","evidence":["Qur'an 33:40"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Muhammad"},{"id":"aqa-rs-a-islam-paper1-1-7-1","paper":"Beliefs","module":"1.7","moduleTitle":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","question":"Which prophet, together with his son Isma'il, is believed to have built (or rebuilt) the Ka'bah?\nA Adam\nB Musa\nC Ibrahim\nD Isa","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C - Qur'an 2:127 describes Ibrahim and Isma'il raising the foundations of the House (the Ka'bah).","evidence":["Qur'an 2:127"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Ibrahim"},{"id":"aqa-rs-a-islam-paper1-1-7-2","paper":"Beliefs","module":"1.7","moduleTitle":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","question":"Give two reasons why Adam is important in Islam.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: he was the first human created by God; he was the first prophet; God made him khalifah (steward) on earth (2:30); God taught him the names of all things (2:31); the angels bowed to him; he repented after disobeying God and was forgiven (2:37), showing God's mercy; he is the father of humanity, showing all humans are equal.","evidence":["Qur'an 2:30-37"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"Adam"},{"id":"aqa-rs-a-islam-paper1-1-7-3","paper":"Beliefs","module":"1.7","moduleTitle":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","question":"Give two events in the life of the Prophet Muhammad.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: born in Makkah around 570 CE; first revelation from Jibril in the Cave of Hira in 610 CE; the Night Journey (al-Isra' wal-Mi'raj); the Hijrah (migration) to Madinah in 622 CE; the Battle of Badr (624 CE); the peaceful return to Makkah and cleansing of the Ka'bah (630 CE); the Farewell Pilgrimage and Sermon (632 CE); his death in Madinah in 632 CE.","evidence":["Qur'an 96:1-5","Qur'an 17:1"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"Muhammad"},{"id":"aqa-rs-a-islam-paper1-1-7-4","paper":"Beliefs","module":"1.7","moduleTitle":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","question":"Explain two ways the Prophet Muhammad is an example for Muslims today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Muslims follow his Sunnah (actions and teachings) in worship. They pray in the way he prayed, perform wudu as he did, and fast and perform Hajj following his example, since the Qur'an calls him 'an excellent example' (33:21).\n\n2. He is a model for character and behaviour. He was known as al-Amin (the trustworthy) even before prophethood, lived simply, was kind to children, animals and the poor, and forgave his enemies when he returned to Makkah. Muslims try to copy this by being honest in business, generous and forgiving in their own relationships.","evidence":["Qur'an 33:21","Sunnah","Al-Amin"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"example of Muhammad"},{"id":"aqa-rs-a-islam-paper1-1-7-5","paper":"Beliefs","module":"1.7","moduleTitle":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","question":"Explain two reasons why Ibrahim is important to Muslims.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. He is a model of Tawhid. He rejected the idols of his people and his father's idol-making, even when threatened with being burned, showing total commitment to the One God. He is called a 'hanif' (pure monotheist) and God's 'friend' (khalil, 4:125).\n\n2. Many Muslim practices go back to him. He and Isma'il built the Ka'bah (2:127), the focus of prayer and Hajj; his willingness to sacrifice his son is remembered at Id-ul-Adha; and the actions of his wife Hajar are re-enacted in the sa'i during Hajj. So every Muslim who prays or performs Hajj follows in his footsteps.","evidence":["Qur'an 4:125","Qur'an 2:127","Qur'an 37:102-107"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"Ibrahim"},{"id":"aqa-rs-a-islam-paper1-1-7-6","paper":"Beliefs","module":"1.7","moduleTitle":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","question":"Explain two Muslim beliefs about Risalah (prophethood).\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. God has sent prophets to every community to teach the same message of Tawhid. 'We certainly sent into every nation a messenger, [saying], \"Worship Allah and avoid false gods\"' (Qur'an 16:36). Tradition says there were 124,000 prophets, of whom 25 are named in the Qur'an, including Adam, Nuh, Ibrahim, Musa and 'Isa.\n\n2. Muhammad is the final prophet, 'the Messenger of Allah and the Seal of the Prophets' (Qur'an 33:40). This means the message given to him is complete and no new prophet will come after him, so Muslims believe the Qur'an and his Sunnah are the final guidance for all people, and the second part of the Shahadah declares that 'Muhammad is the messenger of Allah'.","evidence":["Qur'an 16:36","Qur'an 33:40","Tradition of 124,000 prophets (Musnad Ahmad)"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"Risalah"},{"id":"aqa-rs-a-islam-paper1-1-7-7","paper":"Beliefs","module":"1.7","moduleTitle":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","question":"Explain two reasons why Adam is important in Islam.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Adam was made God's khalifah (steward or representative) on earth. 'I will make upon the earth a successive authority' (Qur'an 2:30). God gave him knowledge, teaching him 'the names of all things' (2:31), and the angels were told to bow to him. This shows the special dignity and responsibility of all humans, who must care for the earth on God's behalf.\n\n2. Adam's story shows God's mercy and forgiveness. Adam and his wife (Hawwa) ate from the forbidden tree after being tempted by Iblis, but they repented and 'Adam received from his Lord words, and He accepted his repentance' (Qur'an 2:37). Muslims therefore do not believe in original sin; each person is born pure (fitrah) and can always return to God through repentance.","evidence":["Qur'an 2:30-31","Qur'an 2:37","Fitrah"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"Adam"},{"id":"aqa-rs-a-islam-paper1-1-7-8","paper":"Beliefs","module":"1.7","moduleTitle":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","question":"‘Muhammad is the most important prophet.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nMuhammad is the 'Seal of the Prophets' (33:40), the final messenger who completed the message given to all earlier prophets. He received the Qur'an, which Muslims believe is God's final, uncorrupted revelation, whereas earlier scriptures have, in Muslim belief, been changed over time. His Sunnah (example), preserved in the Hadith, is the second source of Islamic law and shows Muslims how to pray, fast, give zakah and perform Hajj. He is named in the Shahadah, so every Muslim declares belief in him. The Qur'an calls him 'a mercy to the worlds' (21:107) and 'an excellent example' (33:21), and his message is for all humanity rather than one nation.\n\nARGUMENTS AGAINST THE STATEMENT\nThe Qur'an teaches Muslims to 'make no distinction between any of His messengers' (2:285), meaning all prophets brought the same message of Tawhid and must be equally believed. Each was important for their time. Adam was the first human and first prophet; without him there would be no humanity, and his forgiveness shows God's mercy. Ibrahim is the 'father of the prophets' for Jews, Christians and Muslims; he built the Ka'bah, and Hajj and Id-ul-Adha are based on his life, so he could be said to have founded many Muslim practices. Musa (Moses) is the prophet mentioned most often by name in the Qur'an.\n\nSome Muslims argue it is wrong to rank prophets because only God knows their true status, and focusing too much on any human being risks shirk. Muslims never worship Muhammad, and he described himself as 'a man like you' who receives revelation (18:110).\n\nCONCLUSION\nAll the prophets are respected, and Muslims believe their messages were the same in essence. However, Muhammad's role is unique: he brought the final and complete revelation for all people, and his example is followed in every part of Muslim life today, which is why he is mentioned in the Shahadah. Although 2:285 warns against discriminating in belief, many scholars note that 2:253 says God raised some messengers above others in degree. Weighing this, I agree with the statement: Muhammad is the most important prophet for Muslims, while all prophets deserve equal belief and respect.","evidence":["Qur'an 33:40","Qur'an 21:107","Qur'an 2:285","Qur'an 2:253","Qur'an 18:110"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Muhammad"},{"id":"aqa-rs-a-islam-paper1-1-7-9","paper":"Beliefs","module":"1.7","moduleTitle":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","question":"‘Ibrahim is a better role model than Adam for Muslims today.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nIbrahim is a powerful example of faithfulness under pressure. He challenged the idol worship of his people and his own father, and was willing to be thrown into fire for his belief in one God, which God made 'coolness and safety' (21:69). He was ready to sacrifice his son when commanded (37:102-107), showing total submission (islam) to God. This is inspiring for Muslims today who may face pressure to compromise their beliefs, for example from peers or a secular culture. He is called God's friend (khalil, 4:125) and a model for believers: 'There has already been for you an excellent example in Ibrahim' (60:4). Many practices - the Ka'bah, Hajj, Id-ul-Adha - keep his example alive.\n\nARGUMENTS AGAINST THE STATEMENT\nAdam is also an important role model, perhaps more relatable. Unlike Ibrahim's extraordinary tests, Adam's story is about an ordinary human weakness: he was tempted, made a mistake, and then sincerely repented and was forgiven (2:37). Most people today make mistakes, so Adam teaches the crucial lesson that it is never too late to turn back to God (tawbah). As the first khalifah (2:30), Adam is a role model of stewardship, which is relevant today given climate change and environmental damage. He also reminds Muslims that all people share one ancestor, which is a strong argument against racism - a point the Prophet made in his Farewell Sermon.\n\nSome would argue that neither is the best role model, because the Prophet Muhammad, 'an excellent example' (33:21), is the model Muslims are told most directly to follow, and his life is recorded in far more detail.\n\nCONCLUSION\nBoth prophets teach important lessons: Ibrahim shows unwavering commitment to Tawhid, while Adam shows repentance, stewardship and human equality. In a world with many challenges to faith, Ibrahim's example of courage is especially powerful, but Adam's message of forgiveness may help more people in daily life. I conclude that neither is simply 'better'; each is a role model for a different part of Muslim life, and both point towards the fullest example found in Muhammad.","evidence":["Qur'an 21:69","Qur'an 37:102-107","Qur'an 60:4","Qur'an 2:30-37","Qur'an 33:21"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Adam and Ibrahim"},{"id":"aqa-rs-a-islam-paper1-1-8-0","paper":"Beliefs","module":"1.8","moduleTitle":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","question":"Which holy book do Muslims believe was given to the Prophet Dawud (David)?\nA Tawrat (Torah)\nB Zabur (Psalms)\nC Injil (Gospel)\nD Suhuf (Scrolls)","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - The Qur'an says 'to Dawud We gave the Zabur' (4:163). The Tawrat was given to Musa, the Injil to 'Isa and the Suhuf to Ibrahim.","evidence":["Qur'an 4:163"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"holy books"},{"id":"aqa-rs-a-islam-paper1-1-8-1","paper":"Beliefs","module":"1.8","moduleTitle":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","question":"Over approximately how many years was the Qur'an revealed to Muhammad?\nA 1 year\nB 10 years\nC 23 years\nD 40 years","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C - The revelation began in 610 CE and continued until shortly before the Prophet's death in 632 CE, about 23 years.","evidence":["Qur'an 17:106 (revealed in stages)"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"revelation"},{"id":"aqa-rs-a-islam-paper1-1-8-2","paper":"Beliefs","module":"1.8","moduleTitle":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","question":"Give two holy books, other than the Qur'an, that Muslims believe were revealed by God.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: the Tawrat (Torah), given to Musa; the Zabur (Psalms), given to Dawud; the Injil (Gospel), given to 'Isa; the Suhuf (Scrolls) of Ibrahim.","evidence":["Qur'an 4:163","Qur'an 5:46","Qur'an 87:19"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"holy books"},{"id":"aqa-rs-a-islam-paper1-1-8-3","paper":"Beliefs","module":"1.8","moduleTitle":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","question":"Give two ways Muslims show respect for the Qur'an.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: performing wudu before touching it; keeping it on a high shelf or stand (kursi); wrapping it in cloth; not placing anything on top of it; reciting it in Arabic; memorising it (becoming a hafiz); not eating or talking while it is recited; reading it during Ramadan.","evidence":["Qur'an 56:79 ('none touch it except the purified')"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"respect"},{"id":"aqa-rs-a-islam-paper1-1-8-4","paper":"Beliefs","module":"1.8","moduleTitle":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","question":"Explain two reasons why the Qur'an has authority for Muslims.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Muslims believe it is the direct word of God, revealed in Arabic through Jibril to Muhammad, not written or edited by a human author. This means its teachings are perfect and must be obeyed, and it is the first source of Shari'ah law.\n\n2. Muslims believe it has been perfectly preserved. It was memorised by many Companions, written down during the Prophet's life, compiled under Abu Bakr and standardised under Uthman. Because the Arabic text has not changed, Muslims believe it carries God's message exactly as revealed, unlike earlier scriptures they believe were altered.","evidence":["Qur'an 15:9","Compilation under Abu Bakr and Uthman"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"authority of Qur'an"},{"id":"aqa-rs-a-islam-paper1-1-8-5","paper":"Beliefs","module":"1.8","moduleTitle":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","question":"Explain two contrasting beliefs about the authority of the Torah, Psalms and Gospel for Muslims compared with the Qur'an.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Muslims believe these books were originally genuine revelations from God, so they respect them and the prophets who received them. Rejecting them entirely would contradict the Sunni article of faith in God's books (kutub).\n\n2. However, Muslims believe they do not have the same authority as the Qur'an today, because over time their texts were changed, lost or mixed with human additions (tahrif). The Qur'an is seen as the final, complete and protected revelation that confirms what was true in them and corrects what was changed, so Muslims follow the Qur'an rather than the Bible for guidance.","evidence":["Kutub","Tahrif","Qur'an 5:48"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"earlier books"},{"id":"aqa-rs-a-islam-paper1-1-8-6","paper":"Beliefs","module":"1.8","moduleTitle":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","question":"Explain two Muslim beliefs about the revelation of the Qur'an.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Revelation began on Laylat al-Qadr (the Night of Power) in 610 CE when Jibril appeared to Muhammad in the Cave of Hira and commanded 'Read! In the name of your Lord who created' (Qur'an 96:1). Muhammad was believed to be unable to read or write, which Muslims see as evidence that the Qur'an came from God, not from him.\n\n2. The Qur'an was revealed gradually over about 23 years, in response to events in the Muslim community. 'And [it is] a Qur'an which We have separated [by intervals] that you might recite it to the people over a prolonged period' (Qur'an 17:106). The Prophet's Companions memorised and wrote down each revelation, and the full text was compiled shortly after his death.","evidence":["Qur'an 96:1-5","Qur'an 17:106","Qur'an 97:1"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"revelation"},{"id":"aqa-rs-a-islam-paper1-1-8-7","paper":"Beliefs","module":"1.8","moduleTitle":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","question":"Explain two Muslim beliefs about the holy books revealed before the Qur'an.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. God gave scriptures to earlier prophets: the Tawrat to Musa, the Zabur to Dawud, the Injil to 'Isa and the Scrolls (Suhuf) to Ibrahim. The Qur'an says 'to Dawud We gave the Zabur' (Qur'an 4:163) and that the Injil contained 'guidance and light' (Qur'an 5:46). Muslims must believe these were genuine revelations.\n\n2. Muslims believe these earlier books were not preserved in their original form. The Scrolls of Ibrahim (Qur'an 87:18-19) are lost, and Muslims believe the Torah and Gospel were changed by humans over time. So the Qur'an, which God promised to protect (15:9), acts as a 'criterion' over them and is the final authority.","evidence":["Qur'an 4:163","Qur'an 5:46","Qur'an 87:18-19","Qur'an 15:9"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"earlier books"},{"id":"aqa-rs-a-islam-paper1-1-8-8","paper":"Beliefs","module":"1.8","moduleTitle":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","question":"‘The Qur'an is the only holy book Muslims need.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nMuslims believe the Qur'an is the final and complete revelation from God, given to the 'Seal of the Prophets' (33:40). God promised to protect it: 'Indeed, it is We who sent down the message, and indeed, We will be its guardian' (15:9). Its Arabic text has remained unchanged since it was standardised under Uthman, and millions of Muslims have memorised it word for word. Muslims believe the earlier books - the Tawrat, Zabur, Injil and Suhuf of Ibrahim - have been lost or altered (tahrif), and the Qur'an confirms what was true in them and corrects what was changed (5:48). So in practice Muslims do not need to read the Bible for guidance; the Qur'an contains all the essential teachings.\n\nARGUMENTS AGAINST THE STATEMENT\nBelief in all of God's books is one of the six articles of faith (4:136), so Muslims cannot dismiss the earlier scriptures; they were 'guidance and light' (5:46) and show that God has always guided humanity. Some Muslims value studying the Bible to understand the shared history of the prophets and to build good relations with Jews and Christians, the 'People of the Book'.\n\nAlso, the Qur'an itself is not the only source of authority. Muslims need the Sunnah of the Prophet, recorded in the Hadith, to know how to carry out many commands. For example, the Qur'an commands salah but the details of the rak'ahs and times come mainly from the Sunnah. Shi'a Muslims also rely on the teachings of the Imams and collections such as al-Kafi, and use the Nahj al-Balagha (sermons of Imam Ali). Most Muslims also rely on scholars and Shari'ah to interpret the Qur'an. A small group called 'Qur'anists' claim only the Qur'an is needed, but most Sunni and Shi'a Muslims reject this view.\n\nCONCLUSION\nAs a holy book of revelation, the Qur'an is the only scripture Muslims need for guidance, because they believe it is complete and preserved. However, Muslims are required to believe in the earlier books, and they need the Hadith and scholarship to apply the Qur'an. So the statement is partly true: the Qur'an is the supreme and final holy book, but it is not the only source of authority Muslims need.","evidence":["Qur'an 15:9","Qur'an 5:46","Qur'an 5:48","Qur'an 4:136","Hadith / Sunnah"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"authority of Qur'an"},{"id":"aqa-rs-a-islam-paper1-1-8-9","paper":"Beliefs","module":"1.8","moduleTitle":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","question":"‘The Qur'an should only be read in Arabic.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nMuslims believe the Qur'an was revealed in Arabic: 'Indeed, We have sent it down as an Arabic Qur'an that you might understand' (12:2). The exact Arabic words are believed to be God's speech, so any translation is a human interpretation, not the Qur'an itself. Arabic has meanings, sounds and rhythms that cannot be fully captured in English, and recitation (tajwid) is regarded as a form of worship. Salah must include recitation of al-Fatihah in Arabic, so all Muslims learn some Arabic. Reading in Arabic also unites the worldwide ummah: a Muslim from Britain, Indonesia or Nigeria can pray together using the same words. Many British Muslim children attend madrasah classes to learn to read Qur'anic Arabic, and those who memorise it are honoured as hafiz.\n\nARGUMENTS AGAINST THE STATEMENT\nMost Muslims in the world are not native Arabic speakers, and the Qur'an is meant as guidance for 'all mankind' (2:185). If people only recite the Arabic without understanding it, they may miss its message. Translations - often called 'interpretations of the meaning', such as those by Abdullah Yusuf Ali or Muhammad Abdel Haleem - help Muslims study, reflect on its teachings and apply them to life. The Qur'an repeatedly asks people to reflect: 'Do they not reflect upon the Qur'an?' (4:82). Translations also allow non-Muslims to learn about Islam, which supports da'wah (inviting to Islam) and interfaith understanding.\n\nMany scholars therefore teach a balance: the Arabic is used in worship and is the authoritative text, while translations and tafsir (commentary) are used to understand it. Both Sunni and Shi'a scholars generally accept translations for study.\n\nCONCLUSION\nThe Arabic Qur'an is the only true Qur'an for Muslims and should be used for prayer and recitation. However, if 'read' means studying and understanding, insisting on Arabic alone would prevent most Muslims from fully grasping God's guidance. I therefore disagree with the statement: the Qur'an should be recited in Arabic, but it is right and helpful to read translations alongside it.","evidence":["Qur'an 12:2","Qur'an 2:185","Qur'an 4:82","Tajwid","Translations by Yusuf Ali, Abdel Haleem"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Arabic Qur'an"},{"id":"aqa-rs-a-islam-paper1-1-9-0","paper":"Beliefs","module":"1.9","moduleTitle":"The imamate in Shi'a Islam: its role and significance","question":"Who do Shi'a Muslims believe was the first Imam?\nA Abu Bakr\nB Ali ibn Abi Talib\nC Husayn ibn Ali\nD Muhammad al-Mahdi","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Shi'as believe the Prophet appointed his cousin and son-in-law Ali as the first Imam; Husayn was the third Imam and al-Mahdi the twelfth.","evidence":["Hadith of Ghadir Khumm"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"first Imam"},{"id":"aqa-rs-a-islam-paper1-1-9-1","paper":"Beliefs","module":"1.9","moduleTitle":"The imamate in Shi'a Islam: its role and significance","question":"What do Twelver Shi'a Muslims believe happened to the twelfth Imam, Muhammad al-Mahdi?\nA He was killed at Karbala\nB He went into hiding (occultation) and will return\nC He became the first caliph\nD He wrote the Qur'an","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Twelvers believe the twelfth Imam went into occultation (ghaybah) in the 9th century and will return as the Mahdi to establish justice.","evidence":["Ghaybah (occultation), 874 CE / 941 CE"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Mahdi"},{"id":"aqa-rs-a-islam-paper1-1-9-2","paper":"Beliefs","module":"1.9","moduleTitle":"The imamate in Shi'a Islam: its role and significance","question":"Give two beliefs Shi'a Muslims hold about the Imams.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: they were appointed by God through the Prophet, not elected; they are descendants of the Prophet through Ali and Fatimah; they are ma'sum (sinless/infallible); they are the authoritative interpreters of the Qur'an and Sunnah; there are twelve of them (for Twelvers); the twelfth Imam is hidden and will return as the Mahdi.","evidence":["Imamah as a root of Usul ad-Din"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"beliefs about Imams"},{"id":"aqa-rs-a-islam-paper1-1-9-3","paper":"Beliefs","module":"1.9","moduleTitle":"The imamate in Shi'a Islam: its role and significance","question":"Give two ways Shi'a Muslims show the importance of the Imams today.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: following the guidance of a marja' (senior scholar) as representatives of the hidden Imam; visiting the shrines of the Imams (ziyarat), e.g. Karbala, Najaf, Mashhad; commemorating the death of Imam Husayn at Ashura; paying the Imam's share of khums (sahm al-Imam); praying for the return of the Mahdi; studying the sayings of the Imams (e.g. Nahj al-Balagha).","evidence":["Ziyarat","Sahm al-Imam"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"Imamate today"},{"id":"aqa-rs-a-islam-paper1-1-9-4","paper":"Beliefs","module":"1.9","moduleTitle":"The imamate in Shi'a Islam: its role and significance","question":"Explain two contrasting beliefs about leadership after the death of the Prophet Muhammad.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Sunni Muslims believe the Prophet did not name a successor, so the community chose the leader. The Companions chose Abu Bakr as the first caliph (khalifah), followed by Umar, Uthman and Ali - the four 'rightly guided caliphs'. The caliph was a political and community leader but did not have special religious authority beyond other scholars.\n\n2. Shi'a Muslims believe God, through the Prophet, appointed Ali as his successor at Ghadir Khumm, so leadership should stay within the Prophet's family (Ahl al-Bayt). The Imams were not only rulers but sinless spiritual guides who could interpret the Qur'an without error, which is why Imamah is a root of Usul ad-Din for Shi'as.","evidence":["Ghadir Khumm","Rightly guided caliphs","Ahl al-Bayt"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"succession"},{"id":"aqa-rs-a-islam-paper1-1-9-5","paper":"Beliefs","module":"1.9","moduleTitle":"The imamate in Shi'a Islam: its role and significance","question":"Explain two ways belief in the Imamate influences Shi'a Muslims today.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It affects religious authority. Because the twelfth Imam is in occultation, Twelver Shi'as follow a living marja' at-taqlid (source of emulation), such as Ayatollah Sistani in Najaf, for rulings on matters like fasting or new medical issues. This gives Shi'as a structured system of guidance.\n\n2. It shapes worship and commemorations. Shi'as visit the shrines of the Imams (e.g. Imam Husayn in Karbala, Imam Ali in Najaf); millions walk to Karbala for Arbaeen. They hold majlis (gatherings) at Ashura to mourn Husayn, whose stand against injustice inspires them to oppose oppression in their own lives.","evidence":["Marja' at-taqlid","Arbaeen","Ashura"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"influence"},{"id":"aqa-rs-a-islam-paper1-1-9-6","paper":"Beliefs","module":"1.9","moduleTitle":"The imamate in Shi'a Islam: its role and significance","question":"Explain two reasons why the Imamate is important for Shi'a Muslims.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Shi'as believe the Imams are chosen by God to guide humanity after the Prophet. They point to the Qur'an's words to Ibrahim, 'Indeed, I will make you a leader (imam) for the people' (Qur'an 2:124), showing that leadership is appointed by God. The Prophet's declaration at Ghadir Khumm - 'Of whomever I am master, Ali is his master' - is seen as Ali's appointment. So following the Imams is following God's will.\n\n2. The Imams are believed to be ma'sum (infallible), so they can interpret the Qur'an and Sunnah without error. Shi'as often cite Qur'an 33:33, 'Allah intends only to remove from you the impurity, O people of the [Prophet's] household, and to purify you', as evidence of their purity. This means the teachings of the Imams provide reliable guidance on how to live, and their example - especially Imam Husayn at Karbala - is a model of faith and justice.","evidence":["Qur'an 2:124","Qur'an 33:33","Hadith of Ghadir Khumm"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"importance of Imamate"},{"id":"aqa-rs-a-islam-paper1-1-9-7","paper":"Beliefs","module":"1.9","moduleTitle":"The imamate in Shi'a Islam: its role and significance","question":"Explain two Shi'a beliefs about the twelfth Imam.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Twelver Shi'as believe the twelfth Imam, Muhammad al-Mahdi, did not die but went into occultation (ghaybah). After a 'minor occultation' (874-941 CE), during which he communicated through four deputies, the 'major occultation' began, and he remains alive but hidden by God. Shi'as believe the earth is never without a proof (hujjah) of God, and he is that proof today.\n\n2. He will return at the end of time as the Mahdi ('rightly guided one') to establish justice, alongside the return of 'Isa. A widely reported hadith says he 'will fill the earth with justice as it was filled with oppression' (Abu Dawud). This gives Shi'as hope, and many pray for his return, while senior scholars (marja') guide the community in his absence.","evidence":["Hadith of the Mahdi (Sunan Abu Dawud)","Ghaybah","Hujjah"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"twelfth Imam"},{"id":"aqa-rs-a-islam-paper1-1-9-8","paper":"Beliefs","module":"1.9","moduleTitle":"The imamate in Shi'a Islam: its role and significance","question":"‘Shi'a Muslims are right to believe that the Imams were chosen by God.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nShi'a Muslims believe the Prophet clearly appointed Ali at Ghadir Khumm on the way back from the Farewell Pilgrimage in 632 CE, saying 'Of whomever I am master (mawla), Ali is his master'. This hadith is recorded in both Shi'a and Sunni collections. They argue that the Qur'an presents leadership as a matter of God's choice: God told Ibrahim, 'I will make you a leader (imam) for the people', and added that the promise 'does not include the wrongdoers' (2:124), suggesting that true leaders must be pure and appointed by God. Qur'an 33:33 speaks of God purifying the Prophet's household. It seems unlikely that God would leave the community without clear guidance after the final prophet, and the conflicts that followed the Prophet's death show the need for divinely chosen leaders.\n\nARGUMENTS AGAINST THE STATEMENT\nSunni Muslims, the majority of Muslims, accept the Ghadir Khumm hadith but interpret 'mawla' as 'friend' or 'beloved', meaning the Prophet was asking people to love and support Ali, not appointing him as ruler. They point out that the Qur'an never names Ali or the Imams. They believe the Prophet did not appoint a successor, leaving the community to choose through consultation (shura), as the Qur'an praises those 'whose affair is [determined by] consultation among themselves' (42:38). The Companions chose Abu Bakr, and Ali himself eventually accepted him and later became the fourth caliph. Sunnis also argue that infallibility belongs only to prophets, so claiming it for the Imams raises them too high. A non-religious historian might see the dispute as a political struggle for power rather than divine choice.\n\nCONCLUSION\nBoth sides use the Qur'an and Hadith, and the disagreement depends largely on how texts like the Ghadir Khumm hadith and 2:124 are interpreted. Shi'a arguments show why belief in divinely chosen Imams is reasonable for them, especially given the importance of the Prophet's family. However, because the Qur'an does not explicitly name the Imams and stresses consultation, the Sunni view is also well supported. I conclude that it cannot be shown decisively which view is right; what matters most is that both traditions share the same core beliefs and respect Ali and the Ahl al-Bayt.","evidence":["Hadith of Ghadir Khumm","Qur'an 2:124","Qur'an 33:33","Qur'an 42:38 (shura)"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Imamate debate"},{"id":"aqa-rs-a-islam-paper1-1-9-9","paper":"Beliefs","module":"1.9","moduleTitle":"The imamate in Shi'a Islam: its role and significance","question":"‘The Imamate is still important for Shi'a Muslims today even though the twelfth Imam is hidden.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nImamah is one of the five roots of Usul ad-Din, so for Shi'as it remains a fundamental belief whether or not the Imam is visible. Twelvers believe the twelfth Imam is alive in occultation and remains the proof (hujjah) of God on earth; his eventual return as the Mahdi to 'fill the earth with justice' gives hope in a world of injustice. In his absence, his authority is represented by qualified scholars - the marja' at-taqlid, such as Ayatollah Sistani - so the Imamate still provides living guidance on religious questions. Shi'as pay half of their khums as sahm al-Imam (the Imam's share), which funds schools, mosques and charities.\n\nThe example of the earlier Imams is also very much alive. Each year millions commemorate Imam Husayn at Ashura and walk to Karbala for Arbaeen - often described as one of the largest annual gatherings in the world. Husayn's stand against the tyrant Yazid inspires Shi'as to oppose oppression, and the teachings of Imam Ali in the Nahj al-Balagha are still studied for guidance on justice and leadership.\n\nARGUMENTS AGAINST THE STATEMENT\nSome might argue that because the Imam cannot be seen or consulted, his role has little practical effect, and that in reality Shi'as are guided by scholars and the Qur'an like Sunni Muslims. The occultation has lasted over a thousand years, which may make the belief feel distant to some young British Shi'as. Sunni Muslims do not accept the Imamate at all, so for most Muslims it has no importance. Some Shi'a scholars also disagree about how much authority the marja' should have, for instance over the Iranian idea of wilayat al-faqih (guardianship of the jurist), which suggests uncertainty about how the Imamate works in practice.\n\nCONCLUSION\nAlthough the twelfth Imam is hidden, the Imamate shapes Shi'a authority, giving (khums), worship (ziyarat, Ashura) and hope (the Mahdi's return). Its continuing influence on millions of people shows it is far from irrelevant. I therefore agree with the statement: the Imamate remains central to Shi'a identity and practice today, even if its daily impact comes through scholars and commemorations rather than direct contact with the Imam.","evidence":["Hadith of the Mahdi","Marja' at-taqlid","Sahm al-Imam","Ashura and Arbaeen","Nahj al-Balagha"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Imamate today"}],"paper2":[{"id":"aqa-rs-a-islam-paper2-2-1-0","paper":"Practices","module":"2.1","moduleTitle":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","question":"Which of the following is one of the Ten Obligatory Acts of Shi'a Islam but is NOT one of the Five Pillars of Sunni Islam?\nA Salah\nB Sawm\nC Khums\nD Hajj","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"C - Khums (a one-fifth tax on surplus income) is an obligatory act for Shi'as; salah, sawm and Hajj are shared with the Sunni Five Pillars.","evidence":["Qur'an 8:41"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Ten Obligatory Acts"},{"id":"aqa-rs-a-islam-paper2-2-1-1","paper":"Practices","module":"2.1","moduleTitle":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","question":"What do the Shi'a obligatory acts 'amr bil-ma'ruf' and 'nahi anil-munkar' mean?\nA Fasting and almsgiving\nB Commanding good and forbidding evil\nC Love for and dissociation from\nD Prayer and pilgrimage","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Amr bil-ma'ruf is encouraging what is good and nahi anil-munkar is discouraging what is wrong, based on Qur'an 3:104.","evidence":["Qur'an 3:104"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Ten Obligatory Acts"},{"id":"aqa-rs-a-islam-paper2-2-1-2","paper":"Practices","module":"2.1","moduleTitle":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","question":"Give two of the Five Pillars of Sunni Islam.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: Shahadah (declaration of faith); Salah (prayer); Zakah (almsgiving); Sawm (fasting in Ramadan); Hajj (pilgrimage to Makkah).","evidence":["Hadith: 'Islam is built on five' (Bukhari, Muslim)"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"Five Pillars"},{"id":"aqa-rs-a-islam-paper2-2-1-3","paper":"Practices","module":"2.1","moduleTitle":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","question":"Give two of the Ten Obligatory Acts of Shi'a Islam that are not among the Five Pillars.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: Khums (one-fifth tax); Jihad (struggle); Amr bil-Ma'ruf (commanding what is good); Nahi anil-Munkar (forbidding what is evil); Tawalla (love for and loyalty to the Prophet's family and their followers); Tabarra (dissociation from the enemies of God and the Ahl al-Bayt).","evidence":["Furu' ad-Din (branches of religion)"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"Ten Obligatory Acts"},{"id":"aqa-rs-a-islam-paper2-2-1-4","paper":"Practices","module":"2.1","moduleTitle":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","question":"Explain two differences between the Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Shahadah is a separate pillar for Sunnis but is not listed as one of the Ten Obligatory Acts for Shi'as. Shi'as regard declaring faith as part of the roots of belief (Usul ad-Din), and the Ten Obligatory Acts (furu' ad-Din, 'branches of religion') are the practical duties that grow from those roots.\n\n2. The Ten Obligatory Acts include duties not on the Sunni list, such as khums, tawalla and tabarra. Khums means Shi'as give a fifth of their surplus annual income, half to their marja' for religious purposes; tawalla and tabarra express love for the Prophet's family and rejection of those who oppose them, which reflects the importance of the Imamate in Shi'a Islam.","evidence":["Usul ad-Din and Furu' ad-Din","Khums","Tawalla and tabarra"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"differences"},{"id":"aqa-rs-a-islam-paper2-2-1-5","paper":"Practices","module":"2.1","moduleTitle":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","question":"Explain two reasons why the Five Pillars are important to Sunni Muslims.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. They are the foundation of Muslim practice, taught by the Prophet himself: 'Islam is built on five', just as a building needs pillars to stand. Performing them shows submission (islam) to God and puts the beliefs of iman into action.\n\n2. They unite the worldwide ummah. All Muslims pray facing the Ka'bah, fast in the same month, give zakah and go on Hajj in the same way, which creates a sense of equality and belonging - for example, on Hajj millions of pilgrims from every country wear the same simple white clothing.","evidence":["Hadith: 'Islam is built on five'","Ummah"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"importance"},{"id":"aqa-rs-a-islam-paper2-2-1-6","paper":"Practices","module":"2.1","moduleTitle":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","question":"Explain two of the Ten Obligatory Acts of Shi'a Islam.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Amr bil-Ma'ruf and Nahi anil-Munkar - commanding good and forbidding evil. The Qur'an says 'Let there be from you a nation inviting to good, enjoining what is right and forbidding what is wrong' (Qur'an 3:104). Shi'as believe they have a duty to encourage good behaviour and challenge wrongdoing in society, beginning gently with words and the heart, for example speaking against injustice or encouraging a friend to pray.\n\n2. Khums - giving one-fifth of one's surplus annual income. 'Know that anything you obtain of war booty - then indeed, for Allah is one fifth of it and for the Messenger and for [his] near relatives, orphans, the needy and the traveller' (Qur'an 8:41). Shi'as interpret this as applying to all gains, not just war booty; half is given to the marja' for religious work and half to needy descendants of the Prophet (sayyids).","evidence":["Qur'an 3:104","Qur'an 8:41"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"Ten Obligatory Acts"},{"id":"aqa-rs-a-islam-paper2-2-1-7","paper":"Practices","module":"2.1","moduleTitle":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","question":"Explain two reasons why the Five Pillars are important for Muslims.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. They were taught by the Prophet as the basis of Islam. Ibn Umar reported that the Prophet said: 'Islam is built upon five: testifying that there is no god but Allah and that Muhammad is the Messenger of Allah, establishing prayer, paying zakah, performing Hajj and fasting in Ramadan' (Sahih al-Bukhari, Sahih Muslim). So performing them is the clearest way of obeying God and the Prophet.\n\n2. They shape every part of a Muslim's life and relationship with God and others. Salah connects a Muslim with God five times a day, sawm teaches self-control, and zakah helps the poor, so the pillars together build taqwa (God-consciousness) and a fairer community. The Qur'an says prayer 'prohibits immorality and wrongdoing' (Qur'an 29:45), showing their moral purpose.","evidence":["Hadith of Ibn Umar (Bukhari 8; Muslim 16)","Qur'an 29:45"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"Five Pillars"},{"id":"aqa-rs-a-islam-paper2-2-1-8","paper":"Practices","module":"2.1","moduleTitle":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","question":"‘The Five Pillars are more important than the six articles of faith.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nSome Muslims argue that actions show what a person truly believes. The Five Pillars turn belief into practice: anyone can claim to believe in God, but praying five times a day, fasting for a month and giving away 2.5% of savings require real commitment. The Prophet called them the 'building' of Islam ('Islam is built on five'), so without them faith would have no structure. The pillars also unite the ummah visibly and benefit society - zakah, for example, supports the poor through charities such as the National Zakat Foundation in the UK. The Qur'an repeatedly links faith with action: 'those who believe and do righteous deeds' (e.g. 103:3).\n\nARGUMENTS AGAINST THE STATEMENT\nHowever, the pillars depend on beliefs. Salah only makes sense if there is one God (Tawhid) who hears prayer; Hajj only makes sense if Ibrahim was a prophet; the motive for all the pillars comes from belief in Akhirah and accountability. In the Hadith of Jibril, iman (faith) is described as the foundation, and the first pillar itself, the Shahadah, is a statement of belief. Actions without sincere belief are worthless: 'Actions are judged by intentions' (Bukhari), and someone who prays only to be seen by others is committing riya'. Belief is what makes the actions acceptable to God.\n\nShi'a Muslims frame this as roots and branches: Usul ad-Din (roots of belief) must come first, and the Ten Obligatory Acts are furu' ad-Din (branches). A tree cannot grow branches without roots, suggesting belief is more fundamental. Islam also recognises that some people cannot perform all the pillars - e.g. those too poor for Hajj or too ill to fast - but no Muslim is excused from belief.\n\nCONCLUSION\nThe Five Pillars are essential and express Muslim faith in daily life, so they cannot be separated from belief. However, they rely on the articles of faith for their meaning and purpose, and Islam teaches that sincere belief and intention are what give actions value. I therefore disagree with the statement: the articles of faith are more fundamental, though both belief and practice are needed for a complete Muslim life.","evidence":["Hadith: 'Islam is built on five'","Hadith of Jibril","Hadith: 'Actions are judged by intentions'","Qur'an 103:3","Usul ad-Din / Furu' ad-Din"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"belief and practice"},{"id":"aqa-rs-a-islam-paper2-2-1-9","paper":"Practices","module":"2.1","moduleTitle":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","question":"‘The Ten Obligatory Acts give Shi'a Muslims a better guide to life than the Five Pillars give Sunni Muslims.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nThe Ten Obligatory Acts are broader. As well as salah, sawm, zakah and Hajj, they include khums, jihad, commanding good (amr bil-ma'ruf), forbidding evil (nahi anil-munkar), tawalla and tabarra. This means they cover not only personal worship but also responsibility for society: Shi'as are directly obliged to encourage good and challenge wrongdoing, following Qur'an 3:104. Khums provides substantial funds for religious education, mosques and the poor. Tawalla and tabarra encourage Shi'as to align themselves with good people and against injustice, inspired by Imam Husayn. Some would argue that a list including social justice offers a more complete guide to how to live.\n\nARGUMENTS AGAINST THE STATEMENT\nSunni Muslims also believe in commanding good and forbidding evil (3:104 applies to all Muslims), in jihad, and in giving voluntary charity (sadaqah) beyond zakah; these duties are simply not listed as 'pillars'. The Five Pillars are not meant to be a complete guide to life but the foundations of worship. Sunnis gain guidance from the whole of the Qur'an, the Sunnah and Shari'ah, which cover ethics, family, business and justice. So the difference in lists does not mean Sunnis have less guidance. Also, the Shahadah is a pillar for Sunnis but not one of the Ten Obligatory Acts; Shi'as treat belief as part of Usul ad-Din instead, so the two lists are organised differently rather than one being fuller.\n\nThe four shared practices (salah, sawm, zakah, Hajj) form the core of both lists, showing much more agreement than difference. Comparing them as 'better' or 'worse' could encourage division in the ummah, which the Qur'an warns against (3:103).\n\nCONCLUSION\nThe Ten Obligatory Acts do make some social duties more explicit, which is a strength. However, Sunni Muslims hold many of the same duties through the wider teaching of the Qur'an and Sunnah, and both lists rest on the same core worship. I conclude that neither is a better guide; they are different ways of organising very similar obligations.","evidence":["Qur'an 3:104","Qur'an 3:103","Qur'an 8:41","Five Pillars and Ten Obligatory Acts"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"comparison"},{"id":"aqa-rs-a-islam-paper2-2-2-0","paper":"Practices","module":"2.2","moduleTitle":"Shahadah: declaration of faith and its place in Muslim practice","question":"Which words form the Sunni Shahadah?\nA God is greatest; there is no power except with God\nB There is no god but Allah, and Muhammad is the messenger of Allah\nC In the name of Allah, the Most Gracious, the Most Merciful\nD Glory be to my Lord, the Most High","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - The Shahadah declares belief in Tawhid and in the prophethood of Muhammad. The other options are other phrases used in worship.","evidence":["Shahadah"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"words of Shahadah"},{"id":"aqa-rs-a-islam-paper2-2-2-1","paper":"Practices","module":"2.2","moduleTitle":"Shahadah: declaration of faith and its place in Muslim practice","question":"What phrase do many Shi'a Muslims add to the Shahadah, for example in the call to prayer?\nA 'and Ali is the wali (friend) of Allah'\nB 'and Abu Bakr is the first caliph'\nC 'and the Qur'an is created'\nD 'and Husayn is the final prophet'","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"A - Many Shi'as add 'Ali is the wali of Allah' to express belief in Imamah; most Shi'a scholars regard it as recommended rather than an obligatory part of the Shahadah.","evidence":["Shi'a adhan"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Shi'a Shahadah"},{"id":"aqa-rs-a-islam-paper2-2-2-2","paper":"Practices","module":"2.2","moduleTitle":"Shahadah: declaration of faith and its place in Muslim practice","question":"Give two occasions when Muslims recite the Shahadah.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: in the adhan (call to prayer) whispered into a newborn baby's ear; when converting to Islam (said sincerely before witnesses); as part of daily prayer (in the tashahhud); in the adhan and iqamah before each prayer; ideally as the last words before death; during personal devotion.","evidence":["Adhan","Tashahhud"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"occasions"},{"id":"aqa-rs-a-islam-paper2-2-2-3","paper":"Practices","module":"2.2","moduleTitle":"Shahadah: declaration of faith and its place in Muslim practice","question":"Give two beliefs expressed in the Shahadah.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: belief in the oneness of God (Tawhid); rejection of any other god (no shirk); belief that Muhammad is a messenger/prophet of God (Risalah); (for Shi'as who add the phrase) belief that Ali is the wali of God (Imamah).","evidence":["Tawhid","Risalah"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"meaning"},{"id":"aqa-rs-a-islam-paper2-2-2-4","paper":"Practices","module":"2.2","moduleTitle":"Shahadah: declaration of faith and its place in Muslim practice","question":"Explain two ways the Shahadah is used in Muslim life.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It marks the beginning of a Muslim's life. When a baby is born, the father or a relative often whispers the adhan, which contains the Shahadah, into the baby's right ear so that the first words the child hears declare faith in God.\n\n2. It is how a person becomes a Muslim. A convert sincerely recites the Shahadah, usually in front of Muslim witnesses at a mosque. From that moment they are a member of the ummah and take on the duties of the other pillars. Many Muslims also hope it will be the last words they say before death, so family members gently recite it at a dying person's bedside.","evidence":["Adhan at birth","Conversion"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"use"},{"id":"aqa-rs-a-islam-paper2-2-2-5","paper":"Practices","module":"2.2","moduleTitle":"Shahadah: declaration of faith and its place in Muslim practice","question":"Explain two reasons why the Shahadah is important to Muslims.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It summarises the two most important beliefs of Islam - Tawhid and Risalah - in a single sentence. By saying it, a Muslim confirms that only God is worthy of worship and that Muhammad's message must be followed.\n\n2. It is the foundation of the other pillars. Prayer, fasting, zakah and Hajj only have meaning for someone who accepts the Shahadah; it appears in every call to prayer and in the tashahhud of every salah, so Muslims repeat it many times a day as a constant reminder of their commitment.","evidence":["Tawhid","Risalah","Tashahhud"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"importance"},{"id":"aqa-rs-a-islam-paper2-2-2-6","paper":"Practices","module":"2.2","moduleTitle":"Shahadah: declaration of faith and its place in Muslim practice","question":"Explain two Muslim teachings about the meaning of the Shahadah.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. The first part, 'There is no god but Allah', expresses Tawhid and rejects all other objects of worship. It echoes Surah 112: 'Say, He is Allah, the One' (Qur'an 112:1). It means a Muslim must reject shirk in all forms - idols, but also making money or status into a god.\n\n2. The second part, 'Muhammad is the messenger of Allah', expresses Risalah. The Qur'an says 'Muhammad is not the father of any of your men, but he is the Messenger of Allah and the Seal of the Prophets' (Qur'an 33:40). It means Muslims accept the Qur'an revealed through him as final and commit to following his Sunnah. Many Shi'as add 'Ali is the wali of Allah', expressing their belief in the Imamate.","evidence":["Qur'an 112:1","Qur'an 33:40","Qur'an 3:18 ('Allah witnesses that there is no deity except Him')"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"meaning"},{"id":"aqa-rs-a-islam-paper2-2-2-7","paper":"Practices","module":"2.2","moduleTitle":"Shahadah: declaration of faith and its place in Muslim practice","question":"Explain two reasons why the Shahadah is the first of the Five Pillars.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It is the declaration of belief on which all other practices depend. The Prophet listed it first: 'Islam is built upon five: testifying that there is no god but Allah and that Muhammad is the Messenger of Allah…' (Sahih al-Bukhari). Without belief in God and His messenger, prayer, fasting and pilgrimage would have no purpose.\n\n2. It is what makes someone a Muslim. A convert enters Islam by sincerely reciting it, and the Qur'an itself bears witness that 'there is no deity except Him' (Qur'an 3:18). Because it is the entry point into the faith and expresses Tawhid - the most important belief - it naturally comes first and is repeated throughout a Muslim's life, from birth to death.","evidence":["Hadith: 'Islam is built upon five' (Bukhari)","Qur'an 3:18"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"importance"},{"id":"aqa-rs-a-islam-paper2-2-2-8","paper":"Practices","module":"2.2","moduleTitle":"Shahadah: declaration of faith and its place in Muslim practice","question":"‘Saying the Shahadah is the most important of the Five Pillars.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nThe Shahadah is the declaration of the two central beliefs of Islam, Tawhid and Risalah, and it is the only pillar that makes someone a Muslim. A convert becomes part of the ummah simply by reciting it sincerely. It is listed first in the hadith 'Islam is built upon five', and every other pillar assumes it: there is no point praying to God or going on pilgrimage to His House if you do not believe in Him. It is also the one pillar no one is exempt from: the sick may be excused fasting, the poor from zakah and Hajj, but every Muslim can say the Shahadah. The Prophet taught that whoever's last words are 'there is no god but Allah' will enter paradise (Abu Dawud), which shows how highly it is valued.\n\nARGUMENTS AGAINST THE STATEMENT\nOthers argue that salah is the most important pillar in practice. The Prophet said that 'the first thing a servant will be called to account for on the Day of Judgement is prayer' (Tirmidhi), and salah is performed five times every day, keeping a Muslim constantly aware of God. Words alone are easy to say; the other pillars require sacrifice of time, food and money, and so prove sincerity. The Qur'an repeatedly links belief with action ('those who believe and do righteous deeds'), suggesting the Shahadah is incomplete without the other pillars.\n\nShi'a Muslims do not list the Shahadah as one of the Ten Obligatory Acts, treating belief as part of Usul ad-Din instead, so for them it cannot be compared directly with the practices. Some Muslims would also say the pillars form a whole and should not be ranked - like pillars of a building, removing any one weakens the structure.\n\nCONCLUSION\nSalah and the other pillars are vital ways of living out faith, and saying the Shahadah without meaning it would be worthless. However, the Shahadah's sincere belief is the foundation that gives every other pillar its purpose and is the gateway into Islam. I therefore agree that it is the most important pillar, provided it is understood not just as words but as a lifelong commitment shown through the other pillars.","evidence":["Hadith: 'Islam is built upon five'","Hadith on prayer as first accounted for (Tirmidhi)","Hadith on last words (Abu Dawud)","Usul ad-Din"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Shahadah"},{"id":"aqa-rs-a-islam-paper2-2-2-9","paper":"Practices","module":"2.2","moduleTitle":"Shahadah: declaration of faith and its place in Muslim practice","question":"‘A person only needs to say the Shahadah to be a true Muslim.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nIn Islamic law, a person becomes a Muslim by sincerely reciting the Shahadah; no ceremony, baptism or test is required. The Prophet taught that people should be treated as Muslims if they declare it, and he criticised a Companion who killed a man who had just said it, asking 'Did you open his heart?' (Muslim). Only God can judge what is in a person's heart, so other Muslims should accept anyone who makes the declaration. This reflects God's mercy: anyone, anywhere, can enter Islam simply by believing and saying these words.\n\nARGUMENTS AGAINST THE STATEMENT\nBeing a 'true' Muslim means more than saying words. The word 'Muslim' means 'one who submits' to God, and submission is shown in action. The Qur'an warns against hypocrites (munafiqun) who 'say with their mouths what is not in their hearts' (3:167). The Shahadah must be said with sincere belief and understanding, and it brings obligations: performing salah, fasting, giving zakah and, if able, going on Hajj. A hadith teaches that iman has many branches, the highest being the Shahadah and the lowest removing something harmful from a path (Muslim), showing that faith includes actions. Shi'a Muslims would add that a full understanding of faith includes the five roots of Usul ad-Din and the Ten Obligatory Acts, including loyalty to the Ahl al-Bayt.\n\nMany Muslims believe faith increases and decreases with actions, so someone who says the Shahadah but never prays may be a Muslim in name but not living as a 'true' Muslim. On the other hand, most scholars teach that a Muslim who neglects duties out of weakness is still a Muslim, though a sinful one.\n\nCONCLUSION\nSaying the Shahadah sincerely is enough to enter Islam, and other people have no right to judge someone's heart. However, the statement is about being a 'true' Muslim, which implies living out the commitment. Since the Qur'an and Hadith link faith closely with action, I disagree with the statement: the Shahadah is the necessary starting point, but a true Muslim also lives by the other pillars and Islamic values.","evidence":["Hadith: 'Did you open his heart?' (Muslim)","Qur'an 3:167","Hadith on the branches of faith (Muslim)","Five Pillars"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"Shahadah and practice"},{"id":"aqa-rs-a-islam-paper2-2-3-0","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"What is the name of the ritual washing Muslims perform before salah?\nA Ihram\nB Wudu\nC Rak'ah\nD Qiblah","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Wudu is the ritual washing of hands, mouth, nose, face, arms, head, ears and feet before prayer (Qur'an 5:6).","evidence":["Qur'an 5:6"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"wudu"},{"id":"aqa-rs-a-islam-paper2-2-3-1","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"How many rak'ahs are prayed in the obligatory Fajr (dawn) prayer?\nA Two\nB Three\nC Four\nD Five","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"A - Fajr has two obligatory rak'ahs; Maghrib has three; Zuhr, Asr and Isha have four.","evidence":["Sunnah of the Prophet"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"rak'ahs"},{"id":"aqa-rs-a-islam-paper2-2-3-2","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"Give two of the five daily prayer times.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: Fajr (dawn, before sunrise); Zuhr (just after midday); Asr (afternoon); Maghrib (just after sunset); Isha (night).","evidence":["Qur'an 11:114","Qur'an 17:78"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"prayer times"},{"id":"aqa-rs-a-islam-paper2-2-3-3","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"Give two ways a Muslim prepares for salah.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: performing wudu (or ghusl if required, or tayammum with clean dust if no water); making sure the place and clothes are clean, e.g. using a prayer mat; facing the qiblah (direction of the Ka'bah); dressing modestly; making niyyah (intention) to pray; responding to the adhan.","evidence":["Qur'an 5:6","Qur'an 2:144"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"preparation"},{"id":"aqa-rs-a-islam-paper2-2-3-4","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"Explain two differences in the practice of salah between Sunni and Shi'a Muslims.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Prayer times: Sunni Muslims usually pray five separate times a day, while many Shi'a Muslims combine Zuhr with Asr and Maghrib with Isha, praying at three times a day while still performing all five prayers. Shi'as point to occasions when the Prophet combined prayers even when not travelling.\n\n2. Position and objects: many Shi'as pray with their arms by their sides, while most Sunnis fold their arms across their chest or stomach (though Maliki Sunnis also often pray with arms by their sides). Shi'as also place their forehead on a small tablet of natural clay (a turbah or mohr), often made from the earth of Karbala, because they believe prostration should be on natural earth.","evidence":["Combining prayers (hadith in Sahih Muslim)","Turbah"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"Sunni and Shi'a differences"},{"id":"aqa-rs-a-islam-paper2-2-3-5","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"Explain two ways Jummah prayer is different from salah at other times.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It is a congregational prayer held at midday on Friday, replacing the Zuhr prayer, and it is obligatory for adult Muslim men to attend at the mosque (women may attend but are not required to). 'O you who believe, when the call is made for prayer on Friday, hasten to the remembrance of Allah and leave trade' (62:9).\n\n2. It includes a khutbah (sermon) delivered by the imam before the prayer, often on a current issue or moral topic, and the prayer itself has two rak'ahs instead of the four of Zuhr. In Britain, Muslims often arrange a longer lunch break or school arrangement to attend, and large mosques may hold more than one Jummah session.","evidence":["Qur'an 62:9","Khutbah"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"Jummah"},{"id":"aqa-rs-a-islam-paper2-2-3-6","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"Explain two ways Muslims perform salah, including movements and recitations.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Each prayer is made up of rak'ahs (units of set movements): standing (qiyam) while reciting al-Fatihah and another passage of the Qur'an; bowing (ruku) while praising God; prostrating (sujud) with forehead, nose, palms, knees and toes on the ground; and sitting (julus). Prostration shows complete submission to God.\n\n2. Recitations are in Arabic and begin with 'Allahu Akbar' (God is greatest) to enter the prayer. In the final sitting Muslims recite the tashahhud (including the Shahadah) and blessings on the Prophet, and they end by turning the head to the right and left saying 'as-salamu alaykum wa rahmatullah' (peace be upon you and the mercy of God).","evidence":["Al-Fatihah (Qur'an 1)","Tashahhud"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"how to pray"},{"id":"aqa-rs-a-islam-paper2-2-3-7","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"Explain two reasons why salah is important to Muslims.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It is a direct command from God and brings a Muslim close to Him. 'Indeed, prayer has been decreed upon the believers a decree of specified times' (Qur'an 4:103). Praying five times a day keeps God at the centre of life, and the Prophet described it as the believer's ascent (mi'raj) towards God - the five prayers were given during the Night Journey.\n\n2. It has a moral and spiritual effect, protecting a person from wrongdoing. 'Indeed, prayer prohibits immorality and wrongdoing' (Qur'an 29:45). Regular prayer builds discipline and taqwa, and praying in congregation at the mosque, shoulder to shoulder, shows the equality and unity of the ummah.","evidence":["Qur'an 4:103","Qur'an 29:45","Night Journey (Qur'an 17:1)"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"importance"},{"id":"aqa-rs-a-islam-paper2-2-3-8","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"Explain two features of salah performed at the mosque and at home.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. At the mosque, Muslims pray in congregation (jama'ah) behind an imam, standing in straight rows facing the qiblah, shown by the mihrab (niche) in the wall. The Prophet said 'Prayer in congregation is twenty-seven times better than prayer offered alone' (Sahih al-Bukhari). This is especially important for Jummah on Friday.\n\n2. At home or elsewhere (school, work, while travelling), Muslims can pray anywhere clean using a prayer mat, as the Prophet said 'The earth has been made for me a place of prayer and a means of purification' (Bukhari). They use a compass or app to find the qiblah. Women often pray at home, and families may pray together, with children learning by copying their parents; this shows prayer is part of everyday life, not only for the mosque.","evidence":["Hadith: congregational prayer 27 times better (Bukhari)","Hadith: 'The earth has been made for me a mosque' (Bukhari)","Qur'an 2:144 (qiblah)"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"mosque and home"},{"id":"aqa-rs-a-islam-paper2-2-3-9","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"Explain two different Muslim views about the importance of prayer.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Many Muslims see the five daily prayers as the most important practice after the Shahadah, essential to being a Muslim. The Prophet said 'The first thing for which a servant will be called to account on the Day of Judgement is prayer; if it is sound, the rest of his deeds will be sound' (Tirmidhi). Some scholars even taught that deliberately abandoning prayer altogether takes a person out of Islam.\n\n2. Others emphasise that the inner meaning matters as much as the outer form. The Qur'an warns 'woe to those who pray but are heedless of their prayer, those who make show' (Qur'an 107:4-6). Sufi Muslims especially stress khushu' (humility and concentration) and personal du'a and dhikr alongside salah. For many, a prayer said without thought is less valuable than one said with sincerity, and personal prayer is also important.","evidence":["Hadith on prayer at judgement (Tirmidhi)","Qur'an 107:4-6","Khushu'"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"different views"},{"id":"aqa-rs-a-islam-paper2-2-3-10","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"‘Praying at the mosque is more important than praying at home.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nThe Prophet taught that 'prayer in congregation is twenty-seven times better than prayer offered alone' (Bukhari), and he regularly led prayer in the mosque in Madinah. Jummah prayer on Friday is obligatory for adult men and must be prayed in congregation (62:9). Praying at the mosque brings the ummah together: rich and poor stand shoulder to shoulder in straight rows, showing equality before God. The imam leads the prayer and delivers the khutbah, which educates the community. The mosque is a 'house of God', a peaceful setting that helps concentration, and attending builds friendships and support networks, which can be especially important for Muslims living as a minority in Britain.\n\nARGUMENTS AGAINST THE STATEMENT\nIslam teaches that prayer can be performed anywhere clean: 'The earth has been made for me a place of prayer' (Bukhari). God is immanent and hears every prayer wherever it is offered (2:186), so the place is less important than sincerity (khushu') and intention. Many Muslims cannot get to a mosque five times a day due to school, work, distance or caring responsibilities, and Islam is a practical religion that does not burden people beyond their capacity (2:286). Women are not required to attend the mosque, and some hadiths say a woman's prayer at home is equally or more rewarded (Abu Dawud). The home is also where children first learn to pray by watching their parents, so prayer at home builds faith in the next generation. Voluntary (nafl) prayers were often prayed at home by the Prophet, who said 'Do not make your houses graves' - meaning they should be places of prayer (Bukhari).\n\nShi'a Muslims value congregational prayer too, but many Shi'a communities did not traditionally treat Friday prayer as obligatory during the Imam's absence, showing that views on mosque attendance vary.\n\nCONCLUSION\nCongregational prayer, especially Jummah for men, has a special reward and an important community role. However, God accepts prayer offered sincerely anywhere, and for many Muslims the home is where most prayers take place. I conclude that praying at the mosque is more rewarding when possible, but it is not more important than praying sincerely and regularly, wherever that happens.","evidence":["Hadith: congregational prayer 27 times better","Qur'an 62:9","Qur'an 2:186","Hadith: 'Do not make your houses graves' (Bukhari)","Qur'an 2:286"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"mosque and home"},{"id":"aqa-rs-a-islam-paper2-2-3-11","paper":"Practices","module":"2.3","moduleTitle":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","question":"‘It is too difficult for Muslims in Britain today to pray five times a day.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nPrayer times are fixed by the sun, which in Britain creates challenges. In summer Fajr can be before 3am and Isha after 11pm, making sleep difficult, while in winter Zuhr, Asr and Maghrib are close together during the school or working day. Many workplaces, schools and exam timetables are not designed around prayer, and some Muslims may feel embarrassed or face discrimination when asking for a space or time to pray. Finding a clean place, performing wudu at work, and finding the qiblah in a busy environment can be awkward. For young people, peer pressure and busy lifestyles can make regular prayer hard to maintain.\n\nARGUMENTS AGAINST THE STATEMENT\nIslam is designed to be practical. Each prayer takes only a few minutes, and there is a window of time in which it can be performed rather than one exact moment. Prayer can be done anywhere clean (Bukhari), with a portable mat. If water is unavailable, tayammum (dry ablution) can be used (5:6). Travellers may shorten and combine prayers (4:101). Shi'a Muslims commonly combine Zuhr with Asr and Maghrib with Isha, praying at three times while keeping all five prayers, which fits more easily into a school or work day. Many British universities, airports, hospitals and workplaces now have multi-faith or prayer rooms, and the Equality Act 2010 protects people from religious discrimination. Apps give exact prayer times and the qiblah direction.\n\nMost importantly, Muslims believe God does not 'burden a soul beyond that it can bear' (2:286), and the Qur'an commands prayer 'at specified times' (4:103), so if God requires it, it must be possible. Millions of British Muslims do pray five times a day, showing it can be done.\n\nCONCLUSION\nThere are genuine practical difficulties, especially with long summer days and inflexible schedules. However, Islam's flexibility (prayer windows, combining, tayammum), modern facilities and legal protections mean that, with commitment, it is achievable. I therefore disagree with the statement: praying five times a day in Britain can be challenging, but it is not too difficult.","evidence":["Qur'an 2:286","Qur'an 4:101","Qur'an 4:103","Qur'an 5:6 (tayammum)","Equality Act 2010"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"prayer in Britain"},{"id":"aqa-rs-a-islam-paper2-2-4-0","paper":"Practices","module":"2.4","moduleTitle":"Sawm: the role and significance of fasting during the month of Ramadan","question":"What is Laylat al-Qadr?\nA The festival at the end of Ramadan\nB The night the Qur'an was first revealed to Muhammad\nC The pre-dawn meal during Ramadan\nD The day of standing at Arafat","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Laylat al-Qadr, the Night of Power, is the night in Ramadan when the first verses (96:1-5) were revealed; it is 'better than a thousand months' (97:3).","evidence":["Qur'an 97:1-5","Qur'an 96:1-5"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"Night of Power"},{"id":"aqa-rs-a-islam-paper2-2-4-1","paper":"Practices","module":"2.4","moduleTitle":"Sawm: the role and significance of fasting during the month of Ramadan","question":"What is the name of the meal eaten before dawn during Ramadan?\nA Iftar\nB Suhur\nC Zakat-ul-Fitr\nD Walimah","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Suhur is eaten before dawn; iftar breaks the fast at sunset.","evidence":["Hadith: 'Eat suhur, for in suhur there is blessing' (Bukhari)"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"suhur"},{"id":"aqa-rs-a-islam-paper2-2-4-2","paper":"Practices","module":"2.4","moduleTitle":"Sawm: the role and significance of fasting during the month of Ramadan","question":"Give two groups of people who are exempt from fasting in Ramadan.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: people who are ill; travellers on a long journey; pregnant or breastfeeding women; women who are menstruating; the elderly or frail; children who have not reached puberty; people with mental illness or who cannot understand the obligation.","evidence":["Qur'an 2:184-185"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"exceptions"},{"id":"aqa-rs-a-islam-paper2-2-4-3","paper":"Practices","module":"2.4","moduleTitle":"Sawm: the role and significance of fasting during the month of Ramadan","question":"Give two things Muslims avoid while fasting during daylight hours in Ramadan.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: eating; drinking (including water); smoking; sexual activity; and, as part of the spirit of the fast, lying, gossiping, arguing or bad behaviour.","evidence":["Qur'an 2:187","Hadith: 'Whoever does not give up false speech…' (Bukhari)"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"duties"},{"id":"aqa-rs-a-islam-paper2-2-4-4","paper":"Practices","module":"2.4","moduleTitle":"Sawm: the role and significance of fasting during the month of Ramadan","question":"Explain two benefits of fasting during Ramadan for Muslims.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It develops self-discipline and taqwa (God-consciousness). By giving up food and drink - things normally permitted - Muslims practise controlling their desires and obeying God, which helps them resist wrongdoing throughout the year.\n\n2. It builds empathy and community. Experiencing hunger helps Muslims understand the suffering of the poor, which encourages charity such as zakah and sadaqah, often given during Ramadan. Families and mosques share iftar together, and some UK mosques and charities run 'open iftars' (e.g. the Ramadan Tent Project) inviting neighbours of all faiths.","evidence":["Qur'an 2:183 ('that you may become righteous')","Ramadan Tent Project"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"benefits"},{"id":"aqa-rs-a-islam-paper2-2-4-5","paper":"Practices","module":"2.4","moduleTitle":"Sawm: the role and significance of fasting during the month of Ramadan","question":"Explain two reasons why some Muslims are exempt from fasting.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Islam does not want fasting to cause harm. 'Allah intends for you ease and does not intend for you hardship' (2:185). People who are ill, pregnant, breastfeeding or elderly could damage their health, so they are excused; protecting life is more important than the ritual.\n\n2. Some people cannot fully take on the responsibility, such as young children, or it would be impractical, such as travellers on long journeys. Most must make up missed days later when able; those who cannot ever fast (e.g. the chronically ill or very elderly) pay fidyah - feeding a poor person for each day missed (2:184).","evidence":["Qur'an 2:184-185","Fidyah"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"exceptions"},{"id":"aqa-rs-a-islam-paper2-2-4-6","paper":"Practices","module":"2.4","moduleTitle":"Sawm: the role and significance of fasting during the month of Ramadan","question":"Explain two Muslim teachings about the origins of fasting in Ramadan.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Ramadan is the month in which the Qur'an was first revealed. 'The month of Ramadan [is that] in which was revealed the Qur'an, a guidance for the people' (Qur'an 2:185). Jibril brought the first words, 'Read! In the name of your Lord who created' (96:1-5), to Muhammad on Laylat al-Qadr in 610 CE in the Cave of Hira, where he went to fast and reflect. Fasting is a way of giving thanks for this revelation.\n\n2. Fasting was commanded by God to the early Muslim community in Madinah (in 624 CE, the second year after the Hijrah), and Muslims believe earlier communities were given fasting too: 'Fasting is prescribed for you as it was prescribed for those before you, that you may become righteous' (Qur'an 2:183). This shows fasting as an ancient form of worship connecting Muslims with earlier prophets.","evidence":["Qur'an 2:185","Qur'an 2:183","Qur'an 96:1-5"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"origins"},{"id":"aqa-rs-a-islam-paper2-2-4-7","paper":"Practices","module":"2.4","moduleTitle":"Sawm: the role and significance of fasting during the month of Ramadan","question":"Explain two reasons why the Night of Power is important to Muslims.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It marks the first revelation of the Qur'an. On this night Jibril brought the words 'Read! In the name of your Lord who created, created man from a clinging substance' (Qur'an 96:1-2). This was the beginning of Muhammad's prophethood and of the Qur'an, God's final message, so it is the most significant night in Islamic history.\n\n2. Worship on this night is especially rewarded. 'The Night of Power is better than a thousand months. The angels and the Spirit descend therein by permission of their Lord' (Qur'an 97:3-4). Muslims spend the last ten nights of Ramadan in extra prayer, Qur'an recitation and du'a, and some stay in the mosque in retreat (i'tikaf) hoping to catch it. Sunnis often mark it on the 27th night; Shi'as particularly on the 19th, 21st and 23rd, which also commemorate Imam Ali's martyrdom.","evidence":["Qur'an 96:1-5","Qur'an 97:1-5","I'tikaf"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"Night of Power"},{"id":"aqa-rs-a-islam-paper2-2-4-8","paper":"Practices","module":"2.4","moduleTitle":"Sawm: the role and significance of fasting during the month of Ramadan","question":"‘Fasting during Ramadan does more harm than good.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nFasting from dawn to sunset can be physically demanding, particularly when Ramadan falls in summer in Britain, where fasts can last around 18-19 hours. Lack of food and water may cause tiredness, headaches, dehydration and poor concentration, which can affect schoolwork, exams, driving and safety at work. Some doctors warn that people with conditions such as diabetes can be at risk if they fast without medical advice. Critics also argue that heavy iftar meals and late nights can undo the health benefits, and that young people may feel pressure to fast even when unwell.\n\nARGUMENTS AGAINST THE STATEMENT\nMuslims believe fasting is commanded by God, who wants what is good for people: 'Fasting is prescribed for you… that you may become righteous' (2:183). Its main purpose is spiritual: it develops taqwa, self-control and gratitude, and draws people closer to God through extra prayer, Qur'an reading and the hope of Laylat al-Qadr, 'better than a thousand months' (97:3). It brings social benefits too: empathy with the hungry, increased charity, family meals and community iftars that bring together Muslims and non-Muslims, such as the Ramadan Tent Project in the UK.\n\nIslam also prevents harm through its exceptions: the sick, travellers, pregnant and breastfeeding women, children and the elderly are exempt, because 'Allah intends for you ease and does not intend for you hardship' (2:185). Many scholars say that someone whose health would be damaged must not fast. Some research suggests moderate fasting can have health benefits. The British Islamic Medical Association publishes guidance so Muslims can fast safely.\n\nCONCLUSION\nFasting can be hard, and in some cases it could be harmful - but Islam itself exempts those cases. For healthy adults who follow sensible advice, the spiritual, moral and social benefits are significant. I therefore disagree with the statement: fasting in Ramadan, practised as Islam teaches, does far more good than harm.","evidence":["Qur'an 2:183","Qur'an 2:185","Qur'an 97:3","British Islamic Medical Association guidance"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"benefits and harm"},{"id":"aqa-rs-a-islam-paper2-2-4-9","paper":"Practices","module":"2.4","moduleTitle":"Sawm: the role and significance of fasting during the month of Ramadan","question":"‘The spiritual benefits of Ramadan are more important than the physical act of fasting.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nThe Qur'an gives the purpose of fasting as 'that you may become righteous' (2:183) - a spiritual goal. The Prophet warned that 'whoever does not give up false speech and acting upon it, Allah has no need of his leaving his food and drink' (Bukhari), and that some fasting people gain nothing from their fast but hunger. This shows that simply not eating has no value without inner change. The real heart of Ramadan is drawing closer to God through prayer (including the extra night prayers, tarawih for Sunnis), reading the Qur'an, seeking Laylat al-Qadr and asking forgiveness: 'whoever fasts Ramadan out of faith and seeking reward, his previous sins will be forgiven' (Bukhari). Those exempt from the physical fast can still share fully in these spiritual benefits.\n\nARGUMENTS AGAINST THE STATEMENT\nOn the other hand, the physical act of fasting is the commanded duty and one of the Five Pillars; it cannot be replaced by good intentions. The spiritual benefits come through the physical discipline: going without food and drink is what teaches patience, self-control and empathy with the poor. Islam does not separate body and soul - worship involves both, just as salah requires physical movements. A hadith qudsi says 'Fasting is for Me and I will reward it' (Bukhari), showing that the act itself is specially valued by God. Many Muslims also highlight the social side - shared suhur and iftar, zakat-ul-fitr and community gatherings - which depend on actually fasting together.\n\nCONCLUSION\nThe physical fast and the spiritual benefits are not really in competition: the act of fasting is the means, and greater taqwa and closeness to God are the aim. However, if one must be judged more important, the Qur'an's stated purpose and the Prophet's warnings suggest that a fast without spiritual change misses the point. I therefore agree with the statement, while recognising that for healthy adults the physical fast remains an essential duty that cannot be skipped.","evidence":["Qur'an 2:183","Hadith on false speech (Bukhari)","Hadith on forgiveness (Bukhari)","Hadith qudsi: 'Fasting is for Me' (Bukhari)"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"spiritual benefits"},{"id":"aqa-rs-a-islam-paper2-2-5-0","paper":"Practices","module":"2.5","moduleTitle":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","question":"What percentage of qualifying savings do Muslims usually give as zakah each year?\nA 1%\nB 2.5%\nC 10%\nD 20%","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Zakah is normally 2.5% of wealth held above the nisab for a lunar year; 20% (one-fifth) is khums.","evidence":["Hadith on the rate of zakah (Abu Dawud)"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"how zakah is given"},{"id":"aqa-rs-a-islam-paper2-2-5-1","paper":"Practices","module":"2.5","moduleTitle":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","question":"What is khums?\nA A voluntary gift to charity\nB A Shi'a obligation to give one-fifth of surplus annual income\nC The minimum wealth before zakah is due\nD Charity given at the end of Ramadan","marks":1,"command":"Multiple choice","sourcePage":null,"rubric":"","modelAnswer":"B - Khums is the Shi'a duty of giving one-fifth (20%) of surplus income, based on Qur'an 8:41. Voluntary charity is sadaqah, the minimum is the nisab and end-of-Ramadan charity is zakat-ul-fitr.","evidence":["Qur'an 8:41"],"examTip":"Read all four options before choosing. Only one letter is credited; if you change your mind, make your final choice clear.","answerTopic":"khums"},{"id":"aqa-rs-a-islam-paper2-2-5-2","paper":"Practices","module":"2.5","moduleTitle":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","question":"Give two groups of people who may receive zakah.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of the eight categories in Qur'an 9:60: the poor (fuqara'); the needy (masakin); those who collect and distribute zakah; those whose hearts are to be reconciled (e.g. new Muslims); freeing captives/slaves; people in debt; those working 'in the cause of Allah'; stranded travellers.","evidence":["Qur'an 9:60"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"recipients"},{"id":"aqa-rs-a-islam-paper2-2-5-3","paper":"Practices","module":"2.5","moduleTitle":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","question":"Give two benefits of zakah for those who receive it.","marks":2,"command":"Give","sourcePage":null,"rubric":"","modelAnswer":"Any two of: it meets basic needs such as food, shelter and medicine; it can help them out of debt; it gives them dignity because it is their right, not a favour; it can help them start a business or gain education; it helps them feel part of the community; it helps them celebrate festivals.","evidence":["Qur'an 9:60","Qur'an 51:19 ('the beggar and the deprived')"],"examTip":"Two brief, accurate points earn the two marks - no development is needed, so don't waste time. Don't give two versions of the same point.","answerTopic":"benefits of receipt"},{"id":"aqa-rs-a-islam-paper2-2-5-4","paper":"Practices","module":"2.5","moduleTitle":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","question":"Explain two ways zakah is different from sadaqah.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Zakah is compulsory, but sadaqah is voluntary. Zakah is one of the Five Pillars and a fixed duty for every adult Muslim whose wealth is above the nisab, whereas sadaqah can be given at any time, by anyone, in any amount.\n\n2. Zakah has fixed rules about amount and recipients - normally 2.5% of savings held for a lunar year, given to the eight categories in 9:60 - while sadaqah has no fixed amount and can include non-financial acts; the Prophet said even a smile to your brother is sadaqah (Tirmidhi).","evidence":["Qur'an 9:60","Hadith: 'Your smile… is charity' (Tirmidhi)"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"zakah and sadaqah"},{"id":"aqa-rs-a-islam-paper2-2-5-5","paper":"Practices","module":"2.5","moduleTitle":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","question":"Explain two ways khums is given in Shi'a Islam.","marks":4,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Shi'a Muslims calculate one-fifth (20%) of their surplus annual income - what is left after normal living expenses for the year - and pay it as khums, often on a fixed 'khums date' each year.\n\n2. Khums is divided into two halves. The sahm al-Imam (Imam's share) is given to, or spent with the permission of, a marja' (senior scholar) for religious purposes such as mosques, seminaries and charities; the sahm al-sadat is given to poor descendants of the Prophet (sayyids), who are not allowed to receive zakah from non-sayyids.","evidence":["Qur'an 8:41","Sahm al-Imam and sahm al-sadat"],"examTip":"Give two separate ways/beliefs. For each, make the point (1 mark) and then develop it with an example, explanation or consequence (second mark).","answerTopic":"khums"},{"id":"aqa-rs-a-islam-paper2-2-5-6","paper":"Practices","module":"2.5","moduleTitle":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","question":"Explain two Muslim teachings about the origins and purpose of zakah.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. Zakah is commanded by God, often alongside prayer: 'And establish prayer and give zakah' (Qur'an 2:43). It was made obligatory in Madinah, where the Prophet organised its collection and distribution to support the poor of the first Muslim community. It is a duty to God, not just kindness.\n\n2. The word zakah means 'purification' and 'growth'. Giving it purifies the giver's wealth and soul from greed: 'Take from their wealth a charity by which you purify them and cause them increase' (Qur'an 9:103). Muslims believe all wealth belongs to God and they are only its trustees, so giving zakah keeps them from becoming selfish and reminds them that the poor have a right to part of it.","evidence":["Qur'an 2:43","Qur'an 9:103","Qur'an 57:7 (wealth held in trust)"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"origins and purpose"},{"id":"aqa-rs-a-islam-paper2-2-5-7","paper":"Practices","module":"2.5","moduleTitle":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","question":"Explain two reasons why zakah is important to Muslims.\nRefer to sacred writings or another source of Muslim belief and teaching in your answer.","marks":5,"command":"Explain","sourcePage":null,"rubric":"","modelAnswer":"1. It helps to create a fairer society by redistributing wealth from the rich to those in need. The Qur'an names eight groups who should receive it, beginning with 'the poor and the needy' (Qur'an 9:60). In the UK, charities such as the National Zakat Foundation use zakah to help people with rent, debt and essentials.\n\n2. It is an act of worship that develops the giver spiritually. It is one of the Five Pillars ('Islam is built upon five…', Bukhari) and shows obedience and gratitude to God. Because the giver acknowledges that wealth is a gift from God and not their own achievement, zakah reduces greed and pride and increases compassion, purifying the soul (9:103).","evidence":["Qur'an 9:60","Qur'an 9:103","Hadith: 'Islam is built upon five'"],"examTip":"Two developed points (2 + 2 marks) plus 1 mark for a relevant, accurate reference to sacred writing or another source of Muslim belief and teaching (Qur'an, Hadith, a scholar, a recognised tradition). One accurate reference is enough; name or paraphrase it clearly.","answerTopic":"importance"},{"id":"aqa-rs-a-islam-paper2-2-5-8","paper":"Practices","module":"2.5","moduleTitle":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","question":"‘Giving zakah is the most effective way to end poverty.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nZakah is a compulsory, regular system of redistribution. If every Muslim with wealth above the nisab gave 2.5% every year, the total would be very large - organisations such as Islamic Relief and the UN have estimated global zakah to be worth hundreds of billions of dollars. The Qur'an directs it specifically to the poor, the needy and those in debt (9:60), so it targets the people who need it most. Because it is a right of the poor rather than a favour, it preserves their dignity. Historically, there are reports that under Caliph Umar ibn Abd al-Aziz zakah collectors could find no one poor enough to receive it. In Shi'a Islam, khums adds a further 20% of surplus income, funding schools, clinics and welfare. Charities such as the National Zakat Foundation in the UK show how zakah can be used for long-term help, like paying rent or funding training.\n\nARGUMENTS AGAINST THE STATEMENT\nPoverty has many causes - war, corruption, unfair trade, climate change, lack of education and healthcare - which charity alone cannot fix. Zakah provides help but does not change the structures that keep people poor. Many people argue that governments, fair taxation, fair trade and international aid are more effective at a large scale. Not all Muslims pay zakah correctly, and it is a duty only for Muslims, so it cannot alone end world poverty. Islam itself also teaches other ways to tackle poverty: voluntary sadaqah, interest-free lending (riba is forbidden), working to earn a living, and campaigning for justice. Some argue that the most effective approach is empowering people through education and jobs, which zakah can support but not replace.\n\nCONCLUSION\nZakah is a powerful and well-targeted way to reduce poverty, and if fully practised it would transform many lives. However, poverty's causes are complex, and zakah works best alongside political, economic and educational change. I therefore disagree that it is the most effective way on its own, but it is one of the most important tools for Muslims, as part of Islam's wider commitment to justice.","evidence":["Qur'an 9:60","Qur'an 2:275 (riba forbidden)","National Zakat Foundation","Islamic Relief","Khums (8:41)"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"zakah and poverty"},{"id":"aqa-rs-a-islam-paper2-2-5-9","paper":"Practices","module":"2.5","moduleTitle":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","question":"‘It is fair that Shi'a Muslims pay khums as well as zakah.’\nEvaluate this statement. In your answer you should:\n• refer to Muslim teaching\n• give reasoned arguments to support this statement\n• give reasoned arguments to support a different point of view\n• reach a justified conclusion.","marks":12,"command":"Evaluate","sourcePage":null,"rubric":"","modelAnswer":"ARGUMENTS SUPPORTING THE STATEMENT\nShi'a Muslims believe khums is commanded in the Qur'an: 'Know that anything you obtain… one fifth of it is for Allah and for the Messenger and for [his] near relatives, orphans, the needy and the traveller' (8:41). The Imams taught that 'anything you obtain' (ghanimtum) applies to all gains, not only war booty. If God commands it, Shi'as see it as fair and right. Khums is only paid on surplus income after reasonable living expenses, so it does not push anyone into poverty. It funds religious education, mosques, community centres, hospitals and charities, and supports poor sayyids, who are not permitted to receive ordinary zakah. Many Shi'as feel that giving generously purifies wealth and protects them from greed (9:103), so paying both is a blessing, not a burden.\n\nARGUMENTS AGAINST THE STATEMENT\nSunni Muslims interpret 8:41 as referring only to war booty, so for them khums on income is not a duty, and the Five Pillars require only zakah. From this view, asking Shi'as to give 20% of surplus income on top of zakah could seem a heavy burden, especially for families on modest incomes. Some critics, including some Shi'a reformers, ask how the sahm al-Imam is used, as large sums are controlled by senior scholars, and they want transparency. Others note that in many Shi'a legal rulings, zakah is only due on specific items (such as gold, silver, livestock and certain crops), which is narrower than common Sunni practice, so in practice the overall burden may be balanced differently rather than simply doubled.\n\nCONCLUSION\nWhether it is fair depends partly on how 8:41 is interpreted. For Shi'as, khums is a divine command applied only to surplus income, funding vital religious and social work, so it is fair and even beneficial. Concerns about accountability can be addressed by transparent management. I therefore agree that it is fair for Shi'a Muslims, who freely accept this understanding of the Qur'an, to pay khums as well as zakah.","evidence":["Qur'an 8:41","Qur'an 9:103","Sahm al-Imam / sahm al-sadat"],"examTip":"Use the four bullet points as a plan: Muslim teaching, arguments for, arguments against, justified conclusion. Higher levels need logical chains of reasoning and a judgement that weighs the arguments - not just a list. Spelling, punctuation and grammar may also be credited on 12-mark answers.","answerTopic":"khums"}]},"notes":[{"id":"aqa-rs-a-islam-paper1-1-1","paper":"Beliefs","module":"1.1","title":"The six articles of faith in Sunni Islam and five roots of Usul ad-Din in Shi'a Islam","specFocus":"Know the six articles of faith (Sunni) and the five roots of Usul ad-Din (Shi'a), including key similarities and differences, and be able to explain why they matter.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"Muslims believe faith (iman) has a clear content. The Qur'an names belief in 'Allah, His angels, His books, His messengers and the Last Day' (Qur'an 4:136), and in the well-known Hadith of Jibril the Prophet adds belief in divine decree. Sunni and Shi'a Muslims organise these beliefs slightly differently.\n\nTHE SIX ARTICLES OF FAITH (SUNNI ISLAM)\n1. Tawhid - belief in the oneness of Allah, who has no partners or equals.\n2. Malaikah - belief in angels, beings of light who serve Allah (e.g. Jibril, Mika'il).\n3. Kutub - belief in the holy books: Qur'an, Tawrat (Torah), Zabur (Psalms), Injil (Gospel) and Suhuf (Scrolls of Ibrahim).\n4. Risalah / Rusul - belief in the prophets and messengers, from Adam to Muhammad, the 'Seal of the Prophets' (33:40).\n5. Akhirah / Yawm ad-Din - belief in life after death and the Day of Judgement.\n6. Al-Qadr - belief in predestination: Allah knows and has decreed all things.\n\nTHE FIVE ROOTS OF USUL AD-DIN (SHI'A ISLAM)\nUsul ad-Din means 'roots (foundations) of religion'. Shi'a Muslims (most British Shi'as are Twelvers, Ithna 'Ashari) believe each should be understood personally, not just accepted from others.\n1. Tawhid - oneness of God.\n2. Adalat - God's justice: God is perfectly fair and never acts wrongly, so humans have real free will and are responsible.\n3. Nubuwwah - prophethood, ending with Muhammad.\n4. Imamah - leadership by twelve divinely appointed, sinless (ma'sum) Imams, starting with Ali ibn Abi Talib.\n5. Mi'ad - the Day of Judgement and resurrection.\n\nSIMILARITIES\nBoth begin with Tawhid. Both include prophethood and the afterlife/judgement. Shi'as also believe in angels, holy books and God's decree, although these are not listed as separate roots, and Sunnis also believe God is just.\n\nDIFFERENCES\n- Imamah is a root only for Shi'as. It comes from the belief that the Prophet appointed Ali as his successor (Ghadir Khumm). Sunnis accepted the caliphs chosen by the community (Abu Bakr, Umar, Uthman, Ali).\n- Adalat is stressed by Shi'as; Sunnis list al-Qadr. This reflects different emphases on free will and God's control.\n\nWHY THEY MATTER\nThey are the core of belief, shaping worship (e.g. Shahadah expresses Tawhid and Risalah), morality (accountability on the Day of Judgement) and identity. Many Muslims stress unity: the Amman Message (2004) affirmed Sunni and Shi'a schools as valid Islam, and Qur'an 3:103 urges Muslims not to divide.\n\nKEY TERMS: iman (faith), shirk (associating partners with God - the greatest sin), ummah (worldwide Muslim community), ma'sum (sinless), Ithna 'Ashari (Twelver Shi'a)."},{"id":"aqa-rs-a-islam-paper1-1-2","paper":"Beliefs","module":"1.2","title":"Tawhid (the Oneness of God), Qur'an Surah 112","specFocus":"Know and understand Tawhid, the Oneness of God, with particular reference to Qur'an Surah 112, and how it is expressed in Muslim belief and life.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"TAWHID - THE ONENESS OF GOD\nTawhid (from the Arabic for 'making one') is the belief that Allah is one, unique and without any partner. It is the first article of faith in Sunni Islam and the first root of Usul ad-Din in Shi'a Islam, and the first half of the Shahadah: 'La ilaha illa Allah' - 'There is no god but Allah'. 'Allah' is simply the Arabic word for 'the God', and Arabic-speaking Christians use it too.\n\nSURAH 112 (AL-IKHLAS, 'SINCERITY')\n'Say: He is Allah, the One (Ahad). Allah, the Eternal Refuge (as-Samad). He neither begets nor is born, nor is there to Him any equivalent.' (Qur'an 112:1-4)\n- Ahad - absolutely one; God cannot be divided.\n- As-Samad - self-sufficient; everything depends on Him but He depends on nothing.\n- 'Neither begets nor is born' - God has no parents or children, so Muslims reject the Christian Trinity and the idea that Jesus ('Isa) is God's son, while honouring 'Isa as a great prophet.\n- 'Nothing is equivalent' - God is beyond comparison with creation (see also 42:11, 'There is nothing like unto Him').\nA hadith (Sahih al-Bukhari) reports the Prophet saying this short surah is equal to a third of the Qur'an.\n\nSHIRK\nShirk means associating partners with God - worshipping idols, treating a human as divine, or believing anything has power independent of God. It is the gravest sin: 'Allah does not forgive association with Him, but He forgives what is less than that' (4:48), meaning it is unforgiven if unrepented at death. Many scholars also warn against 'hidden' or 'minor' shirk, such as showing off in worship (riya') or making money or status one's real god.\n\nHOW TAWHID IS EXPRESSED\n- Worship is to God alone, without images or intermediaries; mosques use calligraphy and geometric patterns (aniconism).\n- The Prophet cleared the 360 idols from the Ka'bah in 630 CE.\n- All of life is 'ibadah (worship) because everything belongs to one Creator; there is no split between religious and secular.\n- Unity of humanity: one God created all, so the ummah transcends race and nation.\n- Every prophet preached Tawhid (21:25).\n\nSUNNI AND SHI'A\nBoth put Tawhid first. Shi'a theology links it closely with Adalat (God's justice) and holds that God's attributes are not separate from His essence. Some Muslims (e.g. many Salafis) criticise practices such as praying at saints' shrines as close to shirk, while many Sufis and Shi'as regard visiting shrines (ziyarat) as respectful remembrance and asking for intercession, not worship - an example of diversity in how Tawhid is applied.\n\nKEY TERMS: Tawhid, shirk, Ahad, as-Samad, riya', 'ibadah, Allahu Akbar ('God is greater')."},{"id":"aqa-rs-a-islam-paper1-1-3","paper":"Beliefs","module":"1.3","title":"The nature of God: omnipotence, beneficence, mercy, fairness and justice/Adalat in Shi'a Islam, immanence and transcendence","specFocus":"Know the nature of God: omnipotence, beneficence, mercy, fairness and justice (Adalat in Shi'a Islam), including different ideas about God's relationship with the world: immanence and transcendence.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"Muslims believe God cannot be fully described, but He has revealed something of His nature through His names. Tradition speaks of the 99 'Beautiful Names' (al-Asma' al-Husna), e.g. al-Khaliq (Creator), al-Alim (All-Knowing), al-Ghaffar (Forgiving). Muslims often recite them with prayer beads (subhah/misbaha).\n\nOMNIPOTENCE\nGod is all-powerful (al-Qadir): 'Allah is over all things competent' (2:20). He creates by command: 'His command when He intends a thing is only that He says to it \"Be\", and it is' (36:82). Implications: trust in God (tawakkul), belief in al-Qadr, and accepting that God can do what humans cannot understand. Raises questions about suffering and free will.\n\nBENEFICENCE\nGod is ar-Rahman, the Most Gracious / Beneficent - generous and loving to all creation. He provides the world, food, rain, family, guidance and life itself. Surah 55 (ar-Rahman) repeatedly asks 'Which of the favours of your Lord would you deny?'. Muslims respond with gratitude (shukr) and by caring for creation as khalifah (stewards).\n\nMERCY\nGod is ar-Rahim, the Most Merciful. 113 of the 114 surahs begin 'Bismillah ar-Rahman ar-Rahim'. 'My mercy encompasses all things' (7:156). Hadith qudsi: 'My mercy prevails over My wrath'. God forgives those who sincerely repent (tawbah) - 'do not despair of the mercy of Allah' (39:53). Muslims are to show mercy to others.\n\nFAIRNESS AND JUSTICE / ADALAT\nGod is al-Adl, the Just. 'Allah does not do injustice, even as much as an atom's weight' (4:40). He judges everyone fairly on the Day of Judgement, taking account of intentions and circumstances. For Shi'a Muslims Adalat is one of the five roots of Usul ad-Din: God is perfectly just by nature, so He does not compel people to sin and then punish them - humans therefore have free will. It also motivates Muslims to act justly (5:8) and resist oppression, as Imam Husayn did at Karbala.\n\nIMMANENCE AND TRANSCENDENCE\n- Transcendent: God is beyond the universe, time and human understanding: 'There is nothing like unto Him' (42:11); 'Vision perceives Him not' (6:103). Hence no images of God (aniconism) and great reverence.\n- Immanent: God is close and active in the world: 'We are closer to him than his jugular vein' (50:16); 'I am near; I respond to the call of the caller' (2:186). Hence personal prayer (du'a) and a sense that God sees every action.\nMuslims hold both together (57:3, 'the Outward and the Inward'): transcendent in essence, immanent in knowledge, power and care. Sufi traditions emphasise closeness through dhikr; many theologians stress transcendence to avoid making God like humans.\n\nTENSIONS FOR EVALUATION\n- Mercy vs justice: resolved by repentance offered fairly to all.\n- Omnipotence and benevolence vs suffering: suffering seen as a test (2:155) with justice in the hereafter.\n\nKEY TERMS: al-Asma' al-Husna, ar-Rahman, ar-Rahim, al-Adl, Adalat, tawakkul, tawbah, du'a, dhikr."},{"id":"aqa-rs-a-islam-paper1-1-4","paper":"Beliefs","module":"1.4","title":"Angels, their nature and role, including Jibril and Mika'il","specFocus":"Know Muslim beliefs about angels (malaikah): their nature and role, including Jibril and Mika'il, and why angels are important.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"NATURE OF ANGELS (MALAIKAH)\nBelief in angels is one of the six articles of faith (4:136). Angels are:\n- created from light (hadith in Sahih Muslim), before humans; jinn are made from smokeless fire and humans from clay;\n- without free will - they 'do not disobey Allah in what He commands them but do what they are commanded' (66:6);\n- immortal, sinless, genderless, and do not need food or sleep;\n- usually invisible, though they can take human form (e.g. Jibril in the Hadith of Jibril, or appearing to Maryam, 19:17);\n- constantly worshipping and praising God.\n\nJIBRIL (GABRIEL)\n- The angel of revelation, 'the trustworthy spirit' (26:193), also called Ruh al-Qudus (16:102).\n- Brought the first revelation to Muhammad in the Cave of Hira on Laylat al-Qadr in 610 CE: 'Read! In the name of your Lord who created' (96:1-5), then the rest of the Qur'an over about 23 years (2:97).\n- Announced the birth of 'Isa to Maryam; taught the Prophet how to pray; accompanied him on the Night Journey (al-Isra' wal-Mi'raj, 17:1).\n- Appeared as a man asking the Prophet about Islam, Iman, Ihsan and the Hour (Hadith of Jibril).\n\nMIKA'IL (MICHAEL)\n- Named with Jibril in 2:98. Traditionally the angel of mercy and provision: brings rain, nourishment and sustenance by God's command; shows God's beneficence.\n\nOTHER ANGELS\n- Israfil - will blow the trumpet to begin the Day of Judgement (hadith tradition).\n- Malak al-Mawt (often called Izra'il) - the Angel of Death, who takes souls (32:11).\n- Kiraman Katibin - 'noble recorders' on each shoulder, writing good and bad deeds (82:10-12; 50:17-18).\n- Munkar and Nakir - question the dead in the grave about their Lord, religion and prophet.\n- Ridwan guards Jannah; Malik guards Jahannam (43:77).\n- Angels bowed to Adam at God's command (2:34); Iblis, a jinn (18:50), refused.\n\nWHY ANGELS MATTER\n- They link God and humanity: without Jibril there is no Qur'an.\n- They remind Muslims every deed is recorded, encouraging good conduct even in private.\n- They show God's care and power in creation, death and judgement.\n- They prepare believers for death, the grave and judgement.\n- They give comfort: angels descend on Laylat al-Qadr (97:4) and support believers (41:30).\nSome Muslims turn their heads to the right and left at the end of salah saying 'as-salamu alaykum wa rahmatullah', which many explain as greeting fellow worshippers and the recording angels.\n\nSUNNI AND SHI'A\nBoth believe in angels. Sunnis list them as an article of faith; for Shi'as belief in angels is part of accepting Nubuwwah and the Qur'an, though not a separate root.\n\nKEY TERMS: malaikah, Jibril, Mika'il, Israfil, Kiraman Katibin, Munkar and Nakir, jinn, Iblis."},{"id":"aqa-rs-a-islam-paper1-1-5","paper":"Beliefs","module":"1.5","title":"Predestination and human freedom and its relationship to the Day of Judgement","specFocus":"Know Muslim beliefs about predestination (al-Qadr) and human freedom, including different Sunni and Shi'a emphases, and how these relate to the Day of Judgement.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"AL-QADR - PREDESTINATION / DIVINE DECREE\nAl-Qadr is the sixth Sunni article of faith. It teaches that God knows everything past, present and future, has written it in al-Lawh al-Mahfuz (the Preserved Tablet, 85:21-22), and that nothing happens without His will: 'Indeed, all things We created with predestination' (54:49). Many Sunni scholars describe four levels: God's knowledge ('ilm), His writing (kitabah), His will (mashi'ah) and His creating (khalq).\n\nMuslims express this in everyday language: 'Insha'Allah' (if God wills) about the future (18:23-24), 'Alhamdulillah' (praise be to God) whatever happens, and 'Masha'Allah' (God has willed it) about blessings.\n\nHUMAN FREEDOM\nThe Qur'an also teaches human choice and responsibility:\n- 'Whoever wills - let him believe; whoever wills - let him disbelieve' (18:29).\n- 'Allah will not change the condition of a people until they change what is in themselves' (13:11).\n- Life is a test 'as to which of you is best in deed' (67:2).\n- God does not burden a soul beyond its capacity (2:286).\n\nDIFFERENT VIEWS\n- Sunni (Ash'ari tradition, the most widespread): God wills and creates all things, including human acts, but humans 'acquire' (kasb) responsibility for choices. The balance is ultimately a mystery beyond human understanding.\n- Mu'tazila (historical rationalist school): humans create their own acts; otherwise God's justice would be compromised.\n- Shi'a: because of Adalat (divine justice, a root of Usul ad-Din), God does not force anyone to sin. God's knowledge of what people will choose does not cause their choices. Imam Ja'far al-Sadiq taught 'neither compulsion nor total delegation, but a matter between the two'. Humans have genuine free will within the limits God sets.\n\nRELATIONSHIP TO THE DAY OF JUDGEMENT\n- People are judged on what they freely chose and intended (niyyah), so freedom makes judgement fair.\n- God's complete knowledge, the Preserved Tablet and the recording angels mean nothing is missed.\n- God is just (4:40) and merciful; repentance (tawbah) can change a person's record.\n- Problem: if all is decreed, is judgement fair? Muslim answers: knowing is not forcing; humans do not know their decree so must act responsibly; God's justice guarantees fairness.\n\nINFLUENCE ON LIFE\n- Patience (sabr) and trust (tawakkul) in hard times, e.g. illness or bereavement.\n- Humility in success.\n- Not fatalism: 'Tie your camel and trust in Allah' (Tirmidhi); seek medicine and work hard.\n- Du'a: Muslims believe sincere prayer matters, and a hadith says only du'a can change decree (Tirmidhi), showing that God's plan includes human prayer and effort.\n\nKEY TERMS: al-Qadr, al-Lawh al-Mahfuz, Insha'Allah, sabr, tawakkul, kasb, niyyah, Adalat."},{"id":"aqa-rs-a-islam-paper1-1-6","paper":"Beliefs","module":"1.6","title":"Akhirah (life after death), human responsibility and accountability, resurrection, heaven and hell","specFocus":"Know Muslim beliefs about Akhirah (life after death): human responsibility and accountability, resurrection, the Day of Judgement, heaven (Jannah) and hell (Jahannam), and their influence on Muslims.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"AKHIRAH - LIFE AFTER DEATH\nAkhirah is one of the six Sunni articles of faith; for Shi'as the resurrection and judgement are the root Mi'ad. Muslims believe this life is a test (67:2) and a preparation for eternal life.\n\nDEATH AND BARZAKH\nAt death the Angel of Death takes the soul (32:11). Many Muslims believe two angels, Munkar and Nakir, question the person in the grave about their Lord, religion and prophet. The soul then waits in barzakh ('barrier', 23:100) until the Day of Judgement, experiencing a foretaste of reward or punishment. Muslims bury the dead quickly, facing Makkah, after washing (ghusl) and the janazah prayer. Mourners say 'Inna lillahi wa inna ilayhi raji'un' - 'To Allah we belong and to Him we return' (2:156).\n\nRESURRECTION AND THE DAY OF JUDGEMENT (YAWM AD-DIN / YAWM AL-QIYAMAH)\n- Only God knows when; signs include the return of 'Isa and (in many traditions) the appearance of the Mahdi.\n- Israfil blows the trumpet; all people are raised bodily: 'He will give life to them who produced them the first time' (36:79). This is one reason most Muslims oppose cremation.\n- Each person receives the book of deeds: in the right hand for the saved, in the left for the condemned (69:19-25).\n- Deeds are weighed on the scales (mizan, 101:6-9). Even an atom's weight counts (99:7-8).\n- People cross the bridge as-Sirat over hell (hadith); the righteous cross safely.\n- The Prophet's intercession (shafa'ah) - Shi'as also believe the Imams and Fatimah will intercede.\n\nHEAVEN - JANNAH\nA garden of eternal peace with 'rivers of water... milk... honey' (47:15), shade, family reunion, no pain or hatred (15:47-48). There are levels; the highest is al-Firdaws. The greatest reward is God's pleasure and seeing Him (75:22-23). Some Muslims take the descriptions literally, others as symbols of joys beyond imagination.\n\nHELL - JAHANNAM\nFire 'whose fuel is people and stones' (66:6), with scorching water and pain (4:56). It is punishment for rejecting God and unrepented evil. Many scholars teach that believers with sins may be purified there temporarily, but those who rejected God remain forever.\n\nHUMAN RESPONSIBILITY AND ACCOUNTABILITY\n- Humans are khalifah (stewards, 2:30), given free will and reason.\n- Everyone answers for themselves: 'No bearer of burdens will bear the burden of another' (35:18).\n- Judgement considers intentions (niyyah): 'Actions are judged by intentions' (Bukhari, first hadith).\n- Mercy: sincere tawbah wipes out sins; God's mercy is vast (39:53).\n\nINFLUENCE TODAY\nMotivates honesty, worship and charity; brings comfort in bereavement; encourages justice since wrongs will be put right; shapes funeral and burial practice (e.g. Muslim sections in UK cemeteries).\n\nDEBATES\nIs fear of hell a good motive? (Rabi'a al-Adawiyya: worship from love.) Can a loving God allow hell? Muslims answer that justice and mercy together require accountability.\n\nKEY TERMS: Akhirah, barzakh, Yawm ad-Din, mizan, as-Sirat, shafa'ah, Jannah, al-Firdaws, Jahannam, Mi'ad."},{"id":"aqa-rs-a-islam-paper1-1-7","paper":"Beliefs","module":"1.7","title":"Risalah (Prophethood) including the role and importance of Adam, Ibrahim and Muhammad","specFocus":"Know Muslim beliefs about Risalah (prophethood), including the role and importance of Adam, Ibrahim and Muhammad.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"RISALAH - PROPHETHOOD\nRisalah means 'message'. Prophets (anbiya', singular nabi) and messengers (rusul, singular rasul - prophets who brought a scripture or law) are humans chosen by God to communicate His guidance. Belief in them is a Sunni article of faith and the Shi'a root Nubuwwah.\n- God sent a messenger to every nation (16:36); tradition speaks of 124,000 prophets; 25 are named in the Qur'an.\n- All taught the same core message: Tawhid and accountability (21:25).\n- Prophets are human, not divine (18:110), but are protected by God from major sin (Shi'as stress full infallibility, 'ismah).\n- Muslims must believe in all and 'make no distinction' among them (2:285), though some are raised in rank (2:253).\n- Muslims say 'peace be upon him' (pbuh / alayhis-salam) after naming a prophet.\n\nADAM\n- First human and first prophet, made from clay and given a soul.\n- Appointed khalifah (steward/vicegerent) on earth (2:30); taught 'the names of all things' (2:31).\n- Angels bowed to him; Iblis refused out of pride (2:34; 7:12).\n- Adam and Hawwa ate from the forbidden tree, repented and were forgiven (2:37) - no original sin; humans are born in fitrah (natural purity).\n- Importance: human dignity, stewardship of the earth, equality of all humanity, God's mercy.\n\nIBRAHIM (ABRAHAM)\n- Rejected idolatry of his people and father Azar; saved from fire (21:51-70).\n- A hanif (pure monotheist), 'friend of God' (khalil, 4:125), model of submission (60:4).\n- With Isma'il, built the Ka'bah (2:125-127) and called people to pilgrimage (22:27).\n- Willing to sacrifice his son (37:102-107), remembered at Id-ul-Adha.\n- Received the Scrolls (Suhuf) of Ibrahim (87:19). 'Father' of the prophets through Isma'il and Ishaq.\n\nMUHAMMAD (c. 570-632 CE)\n- Born in Makkah; orphaned young; known as al-Amin (the trustworthy).\n- 610 CE: first revelation in the Cave of Hira on Laylat al-Qadr (96:1-5).\n- Faced persecution in Makkah; Night Journey (17:1) - five daily prayers given.\n- 622 CE: Hijrah to Madinah - start of the Islamic calendar and the first Muslim community.\n- 630 CE: returned to Makkah, cleansed the Ka'bah of idols, forgave opponents.\n- 632 CE: Farewell Sermon at Arafat ('an Arab has no superiority over a non-Arab…'), died in Madinah.\n- 'Seal of the Prophets' (33:40), 'mercy to the worlds' (21:107), 'an excellent example' (33:21). His Sunnah (recorded in the Hadith) is the second source of authority after the Qur'an.\n\nSUNNI AND SHI'A\nBoth accept all prophets and the finality of Muhammad. Shi'as believe the Prophet's family (Ahl al-Bayt) and the Imams continue his guidance (not as prophets) - see Imamate. Sunnis follow the Sunnah as transmitted by the Companions (sahabah); Shi'as prefer hadith transmitted through the Ahl al-Bayt.\n\nTODAY\nMuslims follow the Sunnah in prayer, dress, manners; respect for the Prophet explains strong reactions to insulting cartoons; Mawlid (the Prophet's birthday) is celebrated by many but not all Muslims.\n\nKEY TERMS: Risalah, nabi, rasul, Nubuwwah, khalifah, fitrah, hanif, Sunnah, Hijrah."},{"id":"aqa-rs-a-islam-paper1-1-8","paper":"Beliefs","module":"1.8","title":"The holy books: Qur'an (revelation and authority); the Torah, the Psalms, the Gospel, the Scrolls of Abraham and their authority","specFocus":"Know Muslim beliefs about the holy books: the Qur'an (its revelation and authority) and the Torah (Tawrat), Psalms (Zabur), Gospel (Injil) and Scrolls of Abraham (Suhuf), and their authority.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"KUTUB - THE HOLY BOOKS\nBelief in God's books (kutub) is a Sunni article of faith. Muslims believe God revealed scriptures to several prophets:\n- Suhuf (Scrolls) of Ibrahim - mentioned in 87:18-19 and 53:36-37; now lost.\n- Tawrat (Torah) - given to Musa (Moses).\n- Zabur (Psalms) - given to Dawud (David) (4:163).\n- Injil (Gospel) - given to 'Isa (Jesus), containing 'guidance and light' (5:46). Muslims understand the Injil as the message revealed to 'Isa, not the four Gospels written about him.\n- Qur'an - given to Muhammad, the final revelation.\n\nAUTHORITY OF THE EARLIER BOOKS\nMuslims respect them as originally true revelations, and Jews and Christians are called 'People of the Book' (Ahl al-Kitab). But Muslims believe they were changed, lost or mixed with human writing over time (tahrif; see 2:79), so they do not have full authority today. The Qur'an is 'confirming what was before it… and a criterion over it' (5:48).\n\nTHE QUR'AN - REVELATION\n- Began on Laylat al-Qadr in 610 CE in the Cave of Hira when Jibril commanded 'Iqra!' ('Read/Recite!') (96:1-5; 97:1).\n- Revealed gradually over about 23 years (17:106), in Makkah and Madinah, often in response to events.\n- Muhammad is traditionally described as ummi (unlettered), so the Qur'an's eloquence is seen as a miracle (i'jaz); it challenges anyone to produce a surah like it (2:23).\n- Memorised by Companions (huffaz) and written on materials such as parchment and bones; compiled into one volume under Caliph Abu Bakr (after many huffaz died in battle) and standardised by Caliph Uthman (c. 650 CE), who sent copies to major cities.\n- 114 surahs (chapters) of ayat (verses), arranged mostly by length, not chronology.\n\nTHE QUR'AN - AUTHORITY\n- The literal word of God (kalam Allah) in Arabic: 'We have sent it down as an Arabic Qur'an' (12:2); translations are 'interpretations of the meaning'.\n- Protected by God: 'We will be its guardian' (15:9).\n- Final and complete revelation for all humanity, the first source of Shari'ah, followed by the Sunnah/Hadith, then scholarly consensus and reasoning.\n- Treated with great respect: wudu before handling, placed on a stand, recited with tajwid, memorised by a hafiz, read in full during Ramadan; Muslims recite parts of it in every salah.\n\nSUNNI AND SHI'A\nBoth accept the same Qur'an. Sunni Muslims use hadith collections such as Sahih al-Bukhari and Sahih Muslim; Shi'a Muslims use collections such as al-Kafi and value the sayings of Imam Ali (Nahj al-Balagha). Shi'as believe the Imams were the most authoritative interpreters of the Qur'an.\n\nDEBATES\n- Is the Qur'an alone enough? (Most say Sunnah is also needed; a minority 'Qur'anist' view disagrees.)\n- Should it be read only in Arabic? (Arabic for worship; translations and tafsir for understanding.)\n- Literal vs contextual interpretation of some verses.\n\nKEY TERMS: kutub, Tawrat, Zabur, Injil, Suhuf, tahrif, Ahl al-Kitab, surah, ayah, hafiz, tafsir, tajwid."},{"id":"aqa-rs-a-islam-paper1-1-9","paper":"Beliefs","module":"1.9","title":"The imamate in Shi'a Islam: its role and significance","specFocus":"Know the Shi'a belief in the imamate (Imamah): its origins, the role of the Imams and its significance for Shi'a Muslims, compared with the Sunni understanding of leadership.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"ORIGINS - THE SUCCESSION DISPUTE\nWhen the Prophet died in 632 CE, Muslims disagreed about who should lead the ummah.\n- Sunnis (ahl al-sunnah wal-jama'ah, about 85-90% of Muslims) believe the Prophet did not name a successor. The community chose Abu Bakr as first caliph (khalifah), followed by Umar, Uthman and Ali - the four 'Rightly Guided Caliphs' (al-Khulafa' al-Rashidun). Leadership is by consultation (shura, 42:38).\n- Shi'as ('Shi'at Ali', the party of Ali) believe the Prophet, at God's command, appointed his cousin and son-in-law Ali ibn Abi Talib at Ghadir Khumm (632 CE): 'Of whomever I am master (mawla), Ali is his master.' Sunnis accept the hadith but read mawla as 'friend'.\n\nWHAT IS AN IMAM (SHI'A)?\nIn everyday Islam 'imam' means the person who leads prayer at the mosque. In Shi'a theology the Imams are divinely appointed leaders from the Prophet's family (Ahl al-Bayt), descended from Ali and Fatimah. Imamah is one of the five roots of Usul ad-Din. Key beliefs:\n- Appointed by God (nass), not elected (cf. 2:124 'I will make you an imam for the people').\n- Ma'sum - sinless and infallible, purified (33:33).\n- Possess special knowledge to interpret the Qur'an and Sunnah correctly.\n- Are a 'proof' (hujjah) of God; the earth is never without one.\n- Not prophets - Muhammad remains the Seal of the Prophets.\n\nTHE TWELVE IMAMS (ITHNA 'ASHARI)\nMost Shi'as, including most in Britain, are Twelvers. The Imams include: 1 Ali (d. 661); 2 Hasan; 3 Husayn, martyred at Karbala in 680 CE (commemorated at Ashura); 6 Ja'far al-Sadiq, a great teacher of law (the Ja'fari school); 8 Ali al-Rida (shrine in Mashhad, Iran); 12 Muhammad al-Mahdi. Other Shi'a groups (e.g. Isma'ilis, led today by the Aga Khan, and Zaydis) recognise different lines.\n\nTHE HIDDEN IMAM AND THE MAHDI\nThe twelfth Imam entered the minor occultation (ghaybah) in 874 CE, communicating through four deputies, and the major occultation in 941 CE. Twelvers believe he is alive and will return as the Mahdi with 'Isa to 'fill the earth with justice' (hadith, Abu Dawud). Many Sunnis also believe in a future Mahdi, but not that he is already born and hidden.\n\nROLE AND SIGNIFICANCE TODAY\n- Authority: in the Imam's absence, Shi'as follow a marja' at-taqlid (e.g. Ayatollah Sistani); in Iran, the idea of wilayat al-faqih gives political authority to a senior jurist - not all Shi'as accept this.\n- Khums: half (sahm al-Imam) goes to the marja' for religious and charitable purposes.\n- Worship: ziyarat to shrines in Najaf, Karbala, Mashhad; Arbaeen walk; Ashura majlis and processions (e.g. in London).\n- Example: Husayn's stand against tyranny inspires justice; Ali's sayings (Nahj al-Balagha) guide ethics.\n- Hope: prayer for the Mahdi's return.\n\nKEY TERMS: Imamah, Ahl al-Bayt, ma'sum, nass, ghaybah, Mahdi, marja' at-taqlid, caliph, shura."},{"id":"aqa-rs-a-islam-paper2-2-1","paper":"Practices","module":"2.1","title":"Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam","specFocus":"Know the Five Pillars of Sunni Islam and the Ten Obligatory Acts of Shi'a Islam (the Five Pillars and jihad in both traditions, plus the additional Shi'a duties), and why they are important.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"THE FIVE PILLARS (ARKAN AL-ISLAM) - SUNNI ISLAM\n'Islam is built upon five: testifying that there is no god but Allah and that Muhammad is the Messenger of Allah, establishing prayer, paying zakah, Hajj and fasting Ramadan' (Bukhari 8; Muslim 16).\n1. Shahadah - declaration of faith.\n2. Salah - five daily prayers.\n3. Zakah - almsgiving of 2.5% of savings above the nisab.\n4. Sawm - fasting during Ramadan.\n5. Hajj - pilgrimage to Makkah once in a lifetime if able.\nLike pillars holding up a building, they support the whole of Muslim life. They turn iman (belief) into 'ibadah (worship) and build taqwa (God-consciousness).\n\nTHE TEN OBLIGATORY ACTS (FURU' AD-DIN) - SHI'A ISLAM\nShi'as distinguish the roots (Usul ad-Din - belief) from the branches (Furu' ad-Din - practice). The Ten Obligatory Acts are:\n1. Salah - prayer.\n2. Sawm - fasting.\n3. Zakah - almsgiving.\n4. Khums - one-fifth of surplus annual income (8:41): half to the marja' (sahm al-Imam), half to needy sayyids.\n5. Hajj - pilgrimage.\n6. Jihad - struggle in God's way (greater and lesser).\n7. Amr bil-Ma'ruf - commanding what is good (3:104).\n8. Nahi anil-Munkar - forbidding what is evil (3:104). Shi'a teaching often describes stages: in the heart, with words, then action if appropriate.\n9. Tawalla - love and loyalty towards God, the Prophet, the Imams and the righteous.\n10. Tabarra - dissociation from those who oppose God and the Ahl al-Bayt (and from evil).\n\nSIMILARITIES AND DIFFERENCES\n- Shared: salah, sawm, zakah and Hajj appear in both lists; both traditions treat jihad as a duty (Sunnis do not list it as a pillar but regard it as obligatory in its proper forms).\n- Shahadah is a pillar for Sunnis; Shi'as treat belief within Usul ad-Din (and some add 'Ali is the wali of Allah' in the call to prayer as a recommended, not obligatory, phrase).\n- Khums, tawalla and tabarra are distinctively Shi'a. Sunnis also value commanding good and forbidding evil, but not as a numbered pillar.\n\nWHY THEY MATTER\n- Obedience to God and the Prophet's Sunnah.\n- Discipline and self-control (sawm), connection with God (salah), social justice (zakah, khums), unity and equality of the ummah (Hajj).\n- Intention matters: 'Actions are judged by intentions' (Bukhari). Pillars performed for show (riya') lose value.\n- Exemptions show God does not burden people beyond capacity (2:286), e.g. the sick from fasting, the poor from Hajj and zakah.\n\nCONTEMPORARY EXAMPLES\nUK Muslims juggle salah with school and work (prayer rooms, flexible breaks); zakah supports charities such as Islamic Relief and the National Zakat Foundation; khums funds Shi'a centres such as the Imam Ali Foundation and community projects.\n\nKEY TERMS: arkan al-Islam, furu' ad-Din, khums, amr bil-ma'ruf, nahi anil-munkar, tawalla, tabarra, taqwa, 'ibadah."},{"id":"aqa-rs-a-islam-paper2-2-2","paper":"Practices","module":"2.2","title":"Shahadah: declaration of faith and its place in Muslim practice","specFocus":"Know the Shahadah - the declaration of faith - its meaning, Sunni and Shi'a forms, and its place in Muslim practice.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"THE WORDS\nSunni Shahadah: 'Ashhadu an la ilaha illa Allah, wa ashhadu anna Muhammadan rasul Allah' - 'I bear witness that there is no god but Allah, and I bear witness that Muhammad is the messenger of Allah.'\nMany Shi'a Muslims add: 'wa Aliyyun wali Allah' - 'and Ali is the wali (friend/guardian) of Allah', particularly in the adhan. Most Shi'a scholars teach this is recommended (not an obligatory part of the declaration), expressing belief in Imamah.\n\nMEANING\n- 'No god but Allah' - Tawhid; rejects shirk (cf. 112:1; 3:18).\n- 'Muhammad is the messenger' - Risalah; accepts the Qur'an and Sunnah as final guidance (33:40).\n- 'I bear witness' - not just opinion but a public commitment.\n- Shahadah literally means 'witnessing/testimony'; the word shahid (witness/martyr) has the same root.\n\nPLACE IN MUSLIM PRACTICE\n- First of the Five Pillars for Sunnis ('Islam is built upon five', Bukhari). For Shi'as, it is not one of the Ten Obligatory Acts because belief belongs to Usul ad-Din; the Shahadah expresses Tawhid, Nubuwwah and (with the addition) Imamah.\n- Conversion: a person becomes Muslim by sincerely reciting it, usually before witnesses. No other ritual is required. Converts in the UK (often called 'reverts') may say it at a local mosque.\n- Birth: the adhan, containing the Shahadah, is whispered into a newborn's right ear, so faith is the first thing a child hears.\n- Daily worship: it is in the adhan and iqamah (calls to prayer) and in the tashahhud of every salah, so practising Muslims say it many times a day.\n- Death: Muslims hope it will be their last words; relatives recite it at the bedside. The Prophet said one whose last words are 'la ilaha illa Allah' will enter paradise (Abu Dawud).\n- Art and symbols: it appears in calligraphy on mosque walls and on flags (e.g. Saudi Arabia).\n\nSINCERITY AND ACTION\nThe Shahadah must be said with understanding and sincerity (ikhlas); the Qur'an condemns hypocrites who say what is not in their hearts (3:167). Only God knows a person's heart - the Prophet rebuked a man who killed someone who had declared it ('Did you open his heart?', Muslim). It is the gateway to the other pillars: belief shown through action.\n\nEVALUATION THEMES\n- Is it the most important pillar? (Foundation of all others vs salah as first thing judged.)\n- Is saying it enough to be a 'true' Muslim? (Enters Islam vs lived submission.)\n- Is the Shi'a addition acceptable? (Sunnis reject it as an innovation in the adhan; Shi'as see it as an expression of the Prophet's appointment of Ali at Ghadir Khumm.)\n\nKEY TERMS: Shahadah, ashhadu, Tawhid, Risalah, adhan, iqamah, tashahhud, ikhlas, wali."},{"id":"aqa-rs-a-islam-paper2-2-3","paper":"Practices","module":"2.3","title":"Salah and its significance (including Jummah and Sunni/Shi'a differences)","specFocus":"Know salah and its significance: how and why Muslims pray, including times, directions, ablution (wudu), movements (rak'ahs) and recitations; salah in the home, mosque and elsewhere; Friday prayer (Jummah); key differences between Sunni and Shi'a practice; and different Muslim views about the importance of prayer.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"WHY MUSLIMS PRAY\nSalah is the second pillar and an obligatory act for Shi'as. It is commanded 'at specified times' (4:103), was given to the Prophet on the Night Journey (al-Isra' wal-Mi'raj) - reduced from fifty to five - and 'prohibits immorality and wrongdoing' (29:45). It builds discipline, God-consciousness (taqwa) and unity. 'The first thing a servant will be called to account for is prayer' (Tirmidhi). Salah differs from du'a (personal prayer, in any language) and dhikr (remembrance).\n\nTIMES\nFajr (dawn, 2 rak'ahs), Zuhr (after midday, 4), Asr (afternoon, 4), Maghrib (after sunset, 3), Isha (night, 4). Times follow the sun (11:114; 17:78) and are announced by the adhan from the mosque.\n\nDIRECTION\nMuslims face the qiblah - the Ka'bah in Makkah (2:144); in mosques the mihrab shows the direction. Originally the qiblah was Jerusalem.\n\nABLUTION (WUDU)\nBased on 5:6. Make niyyah (intention), then wash hands, rinse mouth and nose, wash face, arms to the elbows, wipe head and ears, and wash (Sunni) or wipe (Shi'a) feet. Wudu is broken by e.g. using the toilet or sleeping. Ghusl (full wash) is needed in some cases; tayammum uses clean dust if no water is available. Purity of body, clothes and place matters.\n\nMOVEMENTS (RAK'AHS) AND RECITATIONS\nEach rak'ah: takbir ('Allahu Akbar'); qiyam (standing) reciting al-Fatihah (Surah 1) and another passage; ruku (bowing) - 'Glory be to my Lord the Magnificent'; standing; sujud (prostration, twice) - 'Glory be to my Lord the Most High'; julus (sitting). The final sitting includes the tashahhud (with Shahadah) and blessings on the Prophet; prayer ends with taslim ('as-salamu alaykum wa rahmatullah') to right and left.\n\nHOME, MOSQUE AND ELSEWHERE\n- Mosque: congregation in straight rows behind an imam; 'twenty-seven times better' than alone (Bukhari).\n- Home: anywhere clean with a prayer mat ('the earth has been made for me a place of prayer', Bukhari). Women commonly pray at home.\n- Elsewhere: school, work, travel; prayer rooms in UK hospitals, airports, universities; travellers may shorten prayers (4:101).\n\nJUMMAH\nFriday midday congregational prayer (62:9), obligatory for adult men; replaces Zuhr with two rak'ahs after a khutbah (sermon). Many Shi'a scholars historically regarded it as optional during the Imam's occultation; today many Shi'a centres hold it.\n\nSUNNI AND SHI'A DIFFERENCES\n- Shi'as often combine prayers into three sessions (Zuhr+Asr, Maghrib+Isha); Sunnis normally pray at five times (combining mainly when travelling).\n- Shi'as usually pray with arms at their sides; most Sunnis fold arms (Malikis often do not).\n- Shi'as prostrate on a turbah (clay tablet, often from Karbala) or natural material.\n- Small differences in wording of the adhan (Shi'as add 'Ali is the wali of Allah' and 'Hasten to the best of deeds') and in wudu.\n\nDIFFERENT VIEWS ABOUT IMPORTANCE\nMost see salah as essential; some scholars said abandoning it entirely is disbelief. Others stress inner sincerity (khushu') over form (107:4-6); Sufis add dhikr. Debates: mosque vs home; possibility of praying five times in a busy British life.\n\nKEY TERMS: salah, wudu, qiblah, mihrab, rak'ah, sujud, takbir, al-Fatihah, Jummah, khutbah, turbah."},{"id":"aqa-rs-a-islam-paper2-2-4","paper":"Practices","module":"2.4","title":"Sawm: the role and significance of fasting during the month of Ramadan","specFocus":"Know the role and significance of sawm (fasting) during Ramadan, including its origins, duties, benefits, the exceptions and their reasons, and the Night of Power (Qur'an 96:1-5).","sourcePages":"Written to match the published AQA GCSE specification.","summary":"WHAT IS SAWM?\nSawm (fasting) is the fourth Sunni pillar and one of the Shi'a Ten Obligatory Acts. During Ramadan, the ninth month of the lunar Islamic calendar, adult Muslims abstain from food, drink, smoking and sexual activity from dawn (Fajr) until sunset (Maghrib). Because the lunar year is about 11 days shorter than the solar year, Ramadan moves through the seasons; in a British summer fasts can last 18-19 hours.\n\nORIGINS\n- Ramadan is the month the Qur'an was first revealed (2:185). The Prophet was meditating in the Cave of Hira when Jibril brought 96:1-5: 'Read! In the name of your Lord who created…'.\n- Fasting was made obligatory in Madinah in the second year after the Hijrah (624 CE).\n- 'Fasting is prescribed for you as it was prescribed for those before you, that you may become righteous' (2:183) - linking Muslims to earlier prophets.\n\nDUTIES\n- Niyyah (intention) to fast each day (or for the month).\n- Suhur - pre-dawn meal; iftar - breaking the fast at sunset, traditionally with dates and water, following the Prophet's Sunnah.\n- Avoiding bad speech and behaviour: 'Whoever does not give up false speech… Allah has no need of his leaving food and drink' (Bukhari).\n- Extra worship: Qur'an reading (many complete it during the month), tarawih night prayers (Sunni), du'a, i'tikaf (retreat in the mosque) in the last ten days.\n- Zakat-ul-Fitr: charity given before Id prayer so the poor can celebrate.\n- Shi'as typically break the fast slightly later (when the redness in the eastern sky has passed) and observe the anniversary of Imam Ali's martyrdom (21 Ramadan).\n\nBENEFITS\nTaqwa and self-discipline; gratitude for food and blessings; empathy with the poor; forgiveness of sins ('whoever fasts Ramadan out of faith and seeking reward, his previous sins are forgiven', Bukhari); family and community unity - e.g. mosque iftars and the UK's Ramadan Tent Project 'open iftars'; some health benefits for healthy adults.\n\nEXCEPTIONS AND REASONS (2:184-185)\n- The ill, travellers - make up the days later.\n- Pregnant, breastfeeding and menstruating women - make up later.\n- The elderly or chronically ill - pay fidyah (feed a poor person per day).\n- Children before puberty, and those who lack understanding, are not obliged.\nReason: 'Allah intends for you ease and does not intend for you hardship' (2:185) - protecting health and life comes first. Deliberately breaking a fast without reason requires kaffarah (e.g. fasting 60 days or feeding 60 poor people).\n\nTHE NIGHT OF POWER (LAYLAT AL-QADR)\nThe night of the first revelation (96:1-5); 'better than a thousand months; the angels and the Spirit descend therein' (97:3-4). Its exact date is unknown; it is sought in the odd nights of the last ten days - Sunnis often mark the 27th, Shi'as especially the 19th, 21st and 23rd. Muslims stay up in prayer, recitation and du'a.\n\nKEY TERMS: sawm, Ramadan, suhur, iftar, niyyah, fidyah, kaffarah, i'tikaf, tarawih, Laylat al-Qadr, taqwa."},{"id":"aqa-rs-a-islam-paper2-2-5","paper":"Practices","module":"2.5","title":"Zakah: the role and significance of giving alms (including Khums in Shi'a Islam)","specFocus":"Know the role and significance of zakah (almsgiving), including its origins, how and why it is given, the benefits of receipt, and khums in Shi'a Islam.","sourcePages":"Written to match the published AQA GCSE specification.","summary":"WHAT IS ZAKAH?\nZakah is the third Sunni pillar and one of the Shi'a Ten Obligatory Acts. The word means 'purification' and 'growth'. It is a compulsory payment by adult Muslims whose wealth exceeds a minimum threshold (the nisab - traditionally the value of about 85g of gold or 595g of silver) held for one lunar year. It differs from sadaqah, which is voluntary charity of any kind - 'even a smile' (Tirmidhi).\n\nORIGINS\nZakah is commanded throughout the Qur'an, often with prayer: 'establish prayer and give zakah' (2:43). It was organised as a fixed duty in Madinah, where the Prophet appointed collectors and distributed it to the poor. After his death, Caliph Abu Bakr insisted it continue to be paid. Earlier prophets also commanded charity (e.g. 19:31 about 'Isa).\n\nHOW IT IS GIVEN\n- Usually 2.5% of savings, cash, gold, silver and business goods; different rates apply to crops and livestock (Shi'a law limits zakah to specific items such as gold, silver, certain crops and livestock).\n- Many Muslims pay it in Ramadan for greater reward.\n- Given directly, through the mosque, or through charities such as the National Zakat Foundation, Islamic Relief or Muslim Aid. In some countries (e.g. Saudi Arabia, Pakistan) the state collects it.\n- Should be given discreetly to protect the recipient's dignity (2:271).\n- Zakat-ul-Fitr is a separate small payment per person before Id-ul-Fitr.\n\nWHO RECEIVES IT (9:60)\nThe poor; the needy; zakah administrators; those whose hearts are to be reconciled; freeing captives; debtors; 'in the cause of Allah'; stranded travellers.\n\nWHY IT IS GIVEN\n- Obedience to God and a pillar of Islam.\n- Wealth belongs to God; humans are trustees (57:7).\n- Purifies the giver from greed and selfishness: 'Take from their wealth a charity by which you purify them' (9:103).\n- The poor have a right to it (51:19); creates a fairer society and narrows the gap between rich and poor.\n\nBENEFITS OF RECEIPT\nMeets basic needs; relieves debt; preserves dignity (it is a right, not a favour); allows participation in community life and festivals; can provide long-term support (education, business start-up); strengthens the ummah - the giver and receiver are both blessed.\n\nKHUMS IN SHI'A ISLAM\nKhums ('one-fifth') is one of the Ten Obligatory Acts. Based on 8:41 ('one fifth of it is for Allah, the Messenger, near relatives, orphans, the needy and the traveller'), Shi'as pay 20% of surplus annual income (what remains after the year's expenses), as well as on some other gains.\n- Sahm al-Imam (half): given to a marja' (e.g. Ayatollah Sistani's offices) for religious purposes - mosques, seminaries, publishing, charity - on behalf of the hidden Imam.\n- Sahm al-Sadat (half): to needy sayyids (descendants of the Prophet), who may not receive zakah from non-sayyids.\nSunnis understand 8:41 to apply to war booty (and some apply one-fifth to buried treasure), so they do not pay khums on income.\n\nDEBATES: Can zakah end poverty? Is khums on top of zakah fair? Should zakah go to non-Muslims? (Many scholars allow sadaqah to anyone and some allow zakah to non-Muslims in certain categories.)\n\nKEY TERMS: zakah, nisab, sadaqah, zakat-ul-fitr, khums, sahm al-Imam, sayyid, riba."}],"rubrics":{"Beliefs":{"1":"1-mark multiple choice (AO1): one mark for the single correct letter.","12":"12-mark evaluation (AO2). Answers are marked on levels. Level 4 (10-12): a well-argued response that gives reasoned consideration to different points of view, with logical chains of reasoning leading to a judgement supported by accurate knowledge of Muslim teaching. Level 3 (7-9): reasoned consideration of different points of view with logical chains of reasoning drawing on relevant knowledge. Level 2 (4-6): reasoned consideration of one point of view, or recognition of different points of view each supported by reasons. Level 1 (1-3): a point of view with a reason stated in support. Up to 3 further marks for spelling, punctuation and grammar are available on 12-mark answers in the Beliefs section. (Paraphrased summary of AQA's published approach - not an official mark scheme.)","2":"2-mark 'Give two…' / 'Name two…' (AO1): one mark for each correct, distinct point. No development required.","4":"4-mark 'Explain two ways / two contrasting…' (AO1): for each of two points, 1 mark for a simple explanation and 2 marks for a detailed explanation (point + development). Where the question asks for contrasting beliefs or influence, the two points must genuinely differ or be applied to Muslim life.","5":"5-mark 'Explain two… Refer to sacred writings or another source of Muslim belief and teaching' (AO1): for each of two points, 1 mark for a simple and 2 marks for a detailed explanation; plus 1 mark for a relevant, accurate reference to sacred writing (Qur'an, Hadith) or another source of Muslim belief and teaching."},"Practices":{"1":"1-mark multiple choice (AO1): one mark for the single correct letter.","12":"12-mark evaluation (AO2). Answers are marked on levels. Level 4 (10-12): a well-argued response that gives reasoned consideration to different points of view, with logical chains of reasoning leading to a judgement supported by accurate knowledge of Muslim teaching. Level 3 (7-9): reasoned consideration of different points of view with logical chains of reasoning drawing on relevant knowledge. Level 2 (4-6): reasoned consideration of one point of view, or recognition of different points of view each supported by reasons. Level 1 (1-3): a point of view with a reason stated in support. (Paraphrased summary of AQA's published approach - not an official mark scheme.)","2":"2-mark 'Give two…' / 'Name two…' (AO1): one mark for each correct, distinct point. No development required.","4":"4-mark 'Explain two ways / two contrasting…' (AO1): for each of two points, 1 mark for a simple explanation and 2 marks for a detailed explanation (point + development). Where the question asks for contrasting beliefs or influence, the two points must genuinely differ or be applied to Muslim life.","5":"5-mark 'Explain two… Refer to sacred writings or another source of Muslim belief and teaching' (AO1): for each of two points, 1 mark for a simple and 2 marks for a detailed explanation; plus 1 mark for a relevant, accurate reference to sacred writing (Qur'an, Hadith) or another source of Muslim belief and teaching."}},"markingSchema":{"dsl":"SCHEME AQA Religious Studies adaptable guidance\nCOMMAND ALL\nMARKS AUTO\nREQUIRE use accurate subject knowledge and answer the command word\nREQUIRE support religious or non-religious views where the question asks for them\nNEVER invent quotations, sources or official level descriptors\nFEEDBACK be specific, supportive and honest about missing content\n\nCOMMAND Explain\nMARKS AUTO\nAWARD 1 one accurate relevant point\nAWARD 1 a clear linked explanation\n\nCOMMAND Evaluate\nMARKS AUTO\nBAND 9-12 well-argued evaluation with a justified conclusion\nBAND 5-8 relevant discussion with some evaluation\nBAND 1-4 limited points with little evaluation","id":"aqa-rs-generic","references":[{"title":"AQA Religious Studies 8062 specification","url":"https://www.aqa.org.uk/subjects/religious-studies/gcse/religious-studies-8062/specification"},{"title":"AQA scheme of assessment","url":"https://www.aqa.org.uk/subjects/religious-studies/gcse/religious-studies-8062/specification/scheme-of-assessment"}],"sourceNotes":"AQA GCSE RS A uses 1/1/4/6/12 question structures and a separate SPaG overlay. Check the current official specification and mark scheme before relying on a mark estimate.","status":"adaptable","title":"AQA Religious Studies · check and adapt","version":1},"moduleCounts":{"paper1":9,"paper2":5},"meta":{"modulesTotal":14,"paper1QuestionCount":90,"paper2QuestionCount":52,"provenance":"Original practice questions, model answers and revision notes written to the published AQA GCSE Religious Studies A (8062) specification (Component 1, Islam: beliefs and teachings; practices). Not past-paper material and not copied from AQA mark schemes, textbooks or revision guides. Model answers are indicative, not official mark schemes. Short quotations from the Qur'an and Hadith are cited in each question's evidence.","qualification":"AQA GCSE Religious Studies A (8062), Component 1: Islam","questionTotal":142,"title":"AQA GCSE Religious Studies A: Islam"}});
